window.APP_DATA = window.APP_DATA || {};
window.APP_DATA.slang = [
  // 諺語 Grade 1-6（20條）
  { id: "s001", grade: 1, term: "一枝草一點露", kind: "諺語", meaning: "天無絕人之路，每個人都有自己的生存之道，不必絕望。", example: "別灰心，一枝草一點露，總會找到出路的。" },
  { id: "s002", grade: 2, term: "苦盡甘來", kind: "諺語", meaning: "經歷困難和痛苦之後，終會迎來幸福和喜樂的日子。", example: "只要堅持下去，苦盡甘來，你會嚐到成功的滋味。" },
  { id: "s003", grade: 3, term: "一分辛苦一分收穫", kind: "諺語", meaning: "付出多少努力就會得到相應的成果，不勞則無獲。", example: "學習是一分辛苦一分收穫，不可能不花力氣就考高分。" },
  { id: "s004", grade: 4, term: "三思而後行", kind: "諺語", meaning: "做任何事都要經過深思熟慮，不可輕率決定。", example: "重大決定要三思而後行，別一時衝動就後悔。" },
  { id: "s005", grade: 2, term: "知足常樂", kind: "諺語", meaning: "懂得知足就能常保快樂心境，貪心只會帶來煩惱。", example: "有人為了賺更多錢而累得半死，我們卻知足常樂。" },
  { id: "s006", grade: 3, term: "虛心使人進步", kind: "諺語", meaning: "態度謙遜虛心，才能不斷學習進步；自滿就會停滯。", example: "你要虛心使人進步，多聽別人的意見和建議。" },
  { id: "s007", grade: 4, term: "驕傲使人落後", kind: "諺語", meaning: "自傲自滿會導致進步停滯，甚至被超越淘汰。", example: "他因為一次成功就開始驕傲使人落後，結果被同學超越。" },
  { id: "s008", grade: 1, term: "勤能補拙", kind: "諺語", meaning: "靠著勤奮努力可以彌補天賦不足，勤奮是成功的關鍵。", example: "我不是最聰明的，但勤能補拙，我相信能趕上別人。" },
  { id: "s009", grade: 2, term: "天無絕人之路", kind: "諺語", meaning: "即使陷入困境也總會有出路，絕望時不應放棄希望。", example: "失業時很難過，但天無絕人之路，找到了新工作。" },
  { id: "s010", grade: 3, term: "鐵杵磨成繡花針", kind: "諺語", meaning: "只要持之以恆，就算最困難的事也能成功；強調耐心和毅力。", example: "他每天練琴十年，這就是鐵杵磨成繡花針的道理。" },
  { id: "s011", grade: 4, term: "團結力量大", kind: "諺語", meaning: "許多人共同合作的力量遠大於單獨一人的力量。", example: "班級要參加比賽，團結力量大，我們一起加油。" },
  { id: "s012", grade: 1, term: "聞過則喜", kind: "諺語", meaning: "聽到自己的錯誤不會生氣反而高興，因為能改進不足。", example: "媽媽聞過則喜地接受我的批評，決心改改她的脾氣。" },
  { id: "s013", grade: 2, term: "己所不欲勿施於人", kind: "諺語", meaning: "自己不想遭受的待遇，就不要加諸於他人身上。", example: "不要欺負別人，己所不欲勿施於人，要尊重他人。" },
  { id: "s014", grade: 5, term: "千里之行始於足下", kind: "諺語", meaning: "再遠大的目標也是從踏出第一步開始的，強調開始的重要性。", example: "想去環遊世界，千里之行始於足下，先計畫好就出發。" },
  { id: "s015", grade: 3, term: "一日之計在於晨", kind: "諺語", meaning: "一天中最重要的時間是早上，早起能計畫和珍惜一天。", example: "要成功的人都知道一日之計在於晨，早起讀書效率最高。" },
  { id: "s016", grade: 4, term: "一年之計在於春", kind: "諺語", meaning: "一年中最重要的季節是春天，春季計畫決定全年方向。", example: "新年要定好目標，一年之計在於春，別浪費開局。" },
  { id: "s017", grade: 5, term: "好事多磨", kind: "諺語", meaning: "美好的事情往往需要經過許多曲折才能實現。", example: "終於考上理想的學校，好事多磨，但堅持就成功了。" },
  { id: "s018", grade: 6, term: "熟能生巧", kind: "諺語", meaning: "經過反覆練習和實踐，不擅長的事情也能逐漸變得熟練和巧妙。", example: "我剛開始打網球很差，但熟能生巧，現在打得還不錯。" },
  { id: "s019", grade: 5, term: "明月清風不用錢", kind: "諺語", meaning: "自然界的美好不需花錢就能享受，真正的快樂來自簡單。", example: "不必買貴的禮物，明月清風不用錢，一起散步就很開心。" },
  { id: "s020", grade: 6, term: "落花有意流水無情", kind: "諺語", meaning: "單方面的努力或付出若得不到回應，最後只能徒勞無功。", example: "他一直追求那個女生，落花有意流水無情，應該放手了。" },

  // 諺語 Grade 7-9（15條）
  { id: "s021", grade: 7, term: "乘風破浪", kind: "諺語", meaning: "勇敢克服困難，憑著勢頭奮發進取，達到目標。", example: "創業初期很辛苦，但我們乘風破浪，現在公司發展順利。" },
  { id: "s022", grade: 7, term: "志在千里", kind: "諺語", meaning: "有遠大的目標和志向，不為眼前的成就所滿足。", example: "他年紀輕輕就志在千里，立志要改變世界。" },
  { id: "s023", grade: 8, term: "樂極生悲", kind: "諺語", meaning: "過度的快樂和放縱往往會導致後來的悲傷和失落。", example: "度假時樂極生悲，回程班機被颶風吹取消了。" },
  { id: "s024", grade: 8, term: "覆水難收", kind: "諺語", meaning: "已經做出的事情就無法挽回，後悔也沒用，要慎重決定。", example: "傷人的話說出口就覆水難收，所以說話要三思。" },
  { id: "s025", grade: 7, term: "卧虎藏龍", kind: "諺語", meaning: "隱藏著許多傑出人才或強大的實力，不可小看。", example: "這家公司看起來不起眼，但卧虎藏龍，有許多優秀人才。" },
  { id: "s026", grade: 9, term: "畫龍點睛", kind: "諺語", meaning: "最後的關鍵部分能讓整個事物完美，比喻重要的一步。", example: "演講差不多了，最後畫龍點睛，講個感人的故事就完美。" },
  { id: "s027", grade: 8, term: "鳳毛麟角", kind: "諺語", meaning: "稀有珍貴，難得一見，形容人或事物非常罕有。", example: "有道德的商人現在已是鳳毛麟角，難得一見。" },
  { id: "s028", grade: 7, term: "沙裡淘金", kind: "諺語", meaning: "從大量尋常的事物中找出珍貴難得的東西；不怕辛苦找寶藏。", example: "編輯工作就像沙裡淘金，要從海量投稿中挑優秀作品。" },
  { id: "s029", grade: 8, term: "光陰似箭", kind: "諺語", meaning: "時光流逝迅速，就像箭一樣快，轉眼就過去了。", example: "轉眼就大學畢業了，光陰似箭，時間過得真快。" },
  { id: "s030", grade: 9, term: "功虧一簣", kind: "諺語", meaning: "成功在即卻因最後的放鬆而失敗，差一點就能成功。", example: "他複習了整年準備考試，最後一週放鬆導致功虧一簣。" },
  { id: "s031", grade: 7, term: "厚積薄發", kind: "諺語", meaning: "長期累積足夠的實力和知識，然後一舉成功爆發。", example: "他默默努力多年，終於厚積薄發，一舉成名。" },
  { id: "s032", grade: 8, term: "文以載道", kind: "諺語", meaning: "文章和文字可以用來傳載人生的智慧和思想道理。", example: "這位作家文以載道，他的作品充滿人生哲理。" },
  { id: "s033", grade: 9, term: "人以群分", kind: "諺語", meaning: "人會根據志同道合的程度聚在一起，相似的人會聚集。", example: "他交的朋友都是有上進心的，人以群分，朋友質量很重要。" },
  { id: "s034", grade: 7, term: "盡人事聽天命", kind: "諺語", meaning: "已經盡力做好自己的事，剩下的就交由命運決定。", example: "考前準備充分，盡人事聽天命，放心等成績放榜。" },
  { id: "s035", grade: 9, term: "飲水思源", kind: "諺語", meaning: "喝著水時要想起水的來源，比喻不要忘記根本和恩情。", example: "現在成功了也要飲水思源，感謝父母的養育。" },

  // 諺語 Grade 10-12（5條）
  { id: "s036", grade: 10, term: "力不從心", kind: "諺語", meaning: "心裡想做某事，但能力不足以實現，無法如願。", example: "想幫助他解決問題，但力不從心，只好看著他難受。" },
  { id: "s037", grade: 11, term: "不合時宜", kind: "諺語", meaning: "言行或做法不符合現在的時代和情境，顯得過時。", example: "他還用舊時代的思維管理公司，已經不合時宜了。" },
  { id: "s038", grade: 10, term: "道可道非常道", kind: "諺語", meaning: "能用言語表達的道理就不是永恆的真理，強調言語的局限。", example: "真正的禪學真理是道可道非常道，難以言傳。" },
  { id: "s039", grade: 12, term: "舐犢情深", kind: "諺語", meaning: "父母對子女的愛非常深厚，比喻親子間深摯的感情。", example: "他父母舐犢情深，為了孩子什麼都肯做。" },
  { id: "s040", grade: 11, term: "白駒過隙", kind: "諺語", meaning: "時間流逝極快，就像白色的馬快速穿過縫隙一般。", example: "孩子從出生到上大學，白駒過隙，轉眼十八年過去。" },

  // 歇後語 Grade 1-6（10條）
  { id: "s041", grade: 1, term: "泥菩薩過江——自身難保", kind: "歇後語", meaning: "自己的問題都沒解決，無法幫助他人；騎虎難下的困境。", example: "他欠銀行一堆錢，泥菩薩過江——自身難保，哪還能借錢給朋友。" },
  { id: "s042", grade: 2, term: "坐著說話不腰疼——缺乏實踐", kind: "歇後語", meaning: "不親自經歷的人容易說風涼話，評論時不知道困難所在。", example: "他沒做過業務卻說很簡單，坐著說話不腰疼——缺乏實踐。" },
  { id: "s043", grade: 3, term: "隔著玻璃看花——朦朧不清", kind: "歇後語", meaning: "被阻隔看不真切，理解不清楚或信息不完整。", example: "二手房的狀況隔著玻璃看花——朦朧不清，一定要親自看。" },
  { id: "s044", grade: 2, term: "騎著駱駝找馬——貪心不足", kind: "歇後語", meaning: "已經得到了還要更多，永不滿足的貪心態度。", example: "他年薪百萬還在想著出軌賺外快，真是騎著駱駝找馬——貪心不足。" },
  { id: "s045", grade: 3, term: "竹籃打水——一場空", kind: "歇後語", meaning: "白費力氣毫無成果，最後一無所獲，所有努力都完全白費。", example: "他花半年談這個生意，最後竹籃打水——一場空。" },
  { id: "s046", grade: 4, term: "黃鼠狼給雞拜年——別有用心", kind: "歇後語", meaning: "看似友善的態度其實另有目的，暗藏著不良企圖的詭計。", example: "他突然對你特別好，別被騙，那是黃鼠狼給雞拜年——別有用心。" },
  { id: "s047", grade: 4, term: "狗咬呂洞賓——不識好人心", kind: "歇後語", meaning: "對善待自己的人反而不理解，做好事反而被埋怨。", example: "我好心提醒他，他卻生氣，狗咬呂洞賓——不識好人心。" },
  { id: "s048", grade: 5, term: "老鼠尾巴——小得不起眼", kind: "歇後語", meaning: "形容東西極其微小不引人注意，或人的地位和影響力很微不足道。", example: "他在公司的職位很低，只是老鼠尾巴——小得不起眼。" },
  { id: "s049", grade: 6, term: "螞蟻搬家——兵強馬壯", kind: "歇後語", meaning: "螞蟻數量眾多井然有序，比喻人多勢眾力量強大。", example: "新創公司才成立半年，螞蟻搬家——兵強馬壯，人數翻倍。" },
  { id: "s050", grade: 5, term: "瞎子進廚房——摸不著頭腦", kind: "歇後語", meaning: "完全不懂情況也搞不清狀況，感到非常困惑和無措困擾。", example: "第一次做菜，瞎子進廚房——摸不著頭腦，全亂套。" },

  // 歇後語 Grade 7-9（10條）
  { id: "s051", grade: 7, term: "十五個吊桶打水——七上八下", kind: "歇後語", meaning: "心情不安定忐忑不安，時而充滿希望時而又擔心害怕。", example: "面試結果還沒出來，我心裡十五個吊桶打水——七上八下。" },
  { id: "s052", grade: 7, term: "八仙過海——各顯神通", kind: "歇後語", meaning: "各自發揮自己的才能和優勢，在各自擅長的領域各顯其能。", example: "這次專案，八仙過海——各顯神通，每個人都貢獻了獨特的想法。" },
  { id: "s053", grade: 8, term: "刻舟求劍——方法不當", kind: "歇後語", meaning: "用過時錯誤的方法去追求目標，無法適應時代的變化。", example: "他還用十年前的老方法做行銷，刻舟求劍——方法不當。" },
  { id: "s054", grade: 9, term: "紙上談兵——只會空想", kind: "歇後語", meaning: "只靠理論不實踐，空口白牙說得好卻做不出來。", example: "他的商業計畫書寫得漂亮，但紙上談兵——只會空想，執行不力。" },
  { id: "s055", grade: 7, term: "葉公好龍——言行不一", kind: "歇後語", meaning: "嘴上說喜歡但實際並不真心，言語和實際行動完全相反。", example: "他說愛讀書，但從沒看過一本，葉公好龍——言行不一。" },
  { id: "s056", grade: 8, term: "朝三暮四——不守承諾", kind: "歇後語", meaning: "經常改變計畫或承諾，做不到堅持原則的事，反覆無常。", example: "這個政策改了好幾次，朝三暮四——不守承諾，讓人很失望。" },
  { id: "s057", grade: 9, term: "亡羊補牢——為時未晚", kind: "歇後語", meaning: "事情已經發生，只要能夠及時採取補救行動就還有希望。", example: "被騙了一次，趕緊改密碼，亡羊補牢——為時未晚。" },
  { id: "s058", grade: 7, term: "狐假虎威——仗勢欺人", kind: "歇後語", meaning: "借助別人的勢力來欺負弱小無辜的人，是一種很卑鄙的行為。", example: "他靠著父親的權勢欺負同學，狐假虎威——仗勢欺人。" },
  { id: "s059", grade: 9, term: "南轅北轍——背道而馳", kind: "歇後語", meaning: "方向完全相反，進度往反方向進行，無法達成目標。", example: "他想減肥卻每天吃甜點，南轅北轍——背道而馳。" },
  { id: "s060", grade: 8, term: "燒香拜佛——臨時抱佛腳", kind: "歇後語", meaning: "只在陷入困難時才想起求助或祈禱，平時沒有充分準備。", example: "他平時不唸書，考試前一天才燒香拜佛——臨時抱佛腳。" },

  // 歇後語 Grade 10-12（5條）
  { id: "s061", grade: 10, term: "蜘蛛結網——費力布局", kind: "歇後語", meaning: "費盡心思進行複雜的計畫和精心安排，步步為營謀求成功。", example: "他為了這個案子蜘蛛結網——費力布局，花了三個月籌畫。" },
  { id: "s062", grade: 11, term: "馬頭琴——聲聲悲鳴", kind: "歇後語", meaning: "言語或行為中帶著深深的悲傷和哀怨，令人感到心酸。", example: "他辭職信的字句馬頭琴——聲聲悲鳴，充滿失落感。" },
  { id: "s063", grade: 12, term: "夜裡挑燈——自我照亮", kind: "歇後語", meaning: "在黑暗困難中靠自己的力量尋求光明和希望，自我激勵。", example: "失業後他夜裡挑燈——自我照亮，自學新技能準備東山再起。" },
  { id: "s064", grade: 10, term: "蘭花指——細緻優雅", kind: "歇後語", meaning: "動作或言語細膩優美精緻，整體充滿高雅的藝術氣息。", example: "她講話像蘭花指——細緻優雅，每個字都帶著韻味。" },
  { id: "s065", grade: 11, term: "鼠目寸光——目光短淺", kind: "歇後語", meaning: "只看眼前的利益而看不遠方，缺乏遠大的眼光和見解。", example: "只想著短期利潤，鼠目寸光——目光短淺，公司無法長期發展。" },

  // 俚語 Grade 1-6（5條）
  { id: "s066", grade: 1, term: "呷緊弄破碗", kind: "俚語", meaning: "吃飯太急會造成碗破裂；比喻做事太急躁反而容易出錯。", example: "做功課不要呷緊弄破碗，慢慢來反而更快完成。" },
  { id: "s067", grade: 2, term: "一粒老鼠屎壞了一鍋粥", kind: "俚語", meaning: "一個壞人或一個小錯誤就能毀掉整個好事的成果。", example: "隊伍裡有個人不認真，一粒老鼠屎壞了一鍋粥，整隊都被扣分。" },
  { id: "s068", grade: 3, term: "拍馬屁", kind: "俚語", meaning: "奉承和討好別人，說些虛偽好聽的話來獲得歡心。", example: "他整天對老師拍馬屁，要是有真本事才更厲害。" },
  { id: "s069", grade: 4, term: "放牛吃草", kind: "俚語", meaning: "不管不問，完全任其自由發展，採取放任不管的態度。", example: "父母放牛吃草讓他自己安排時間，他竟然自律地主動讀書。" },
  { id: "s070", grade: 5, term: "小鼻子小眼睛", kind: "俚語", meaning: "形容人非常小氣計較，對每件小事都斤斤計較不放。", example: "他小鼻子小眼睛的，朋友欠他五塊錢也一直記著。" },

  // 俚語 Grade 7-9（5條）
  { id: "s071", grade: 7, term: "唱雙簧", kind: "俚語", meaning: "兩個人互相配合表演和演戲，共同進行欺騙或詭計。", example: "他們倆唱雙簧騙老師說作業丟了，結果被揭穿。" },
  { id: "s072", grade: 8, term: "吃不了兜著走", kind: "俚語", meaning: "做了壞事或承諾做的事情就必須承受後果，無法逃脫。", example: "你既然答應了就要做到，吃不了兜著走，要負責任。" },
  { id: "s073", grade: 7, term: "拿翹", kind: "俚語", meaning: "欠債不還或不履行承諾，逃避應負的責任和義務。", example: "他工作四個月就拿翹不來了，老闆找不到他。" },
  { id: "s074", grade: 9, term: "腳踏兩條船", kind: "俚語", meaning: "同時與兩個人有曖昧或婚外情關係，對感情不忠實。", example: "他被發現腳踏兩條船，兩段感情都破裂了。" },
  { id: "s075", grade: 8, term: "撇清界線", kind: "俚語", meaning: "主動切斷彼此的關係，表示不再往來或承認關係。", example: "他們吵完架後馬上撇清界線，從此沒有往來。" },

  // 俚語 Grade 10-12（5條）
  { id: "s076", grade: 10, term: "牛頭馬面", kind: "俚語", meaning: "形容人長相凶惡難看，或指某人為人陰險毒辣的類型。", example: "他雖然牛頭馬面的，但其實是個溫柔的人。" },
  { id: "s077", grade: 11, term: "狐朋狗友", kind: "俚語", meaning: "指不良的朋友或損友，是會帶壞人的不好交往對象。", example: "他跟了一群狐朋狗友後開始逃課，家長非常擔心。" },
  { id: "s078", grade: 12, term: "死皮賴臉", kind: "俚語", meaning: "厚著臉皮不停乞求或跟著不願離開，毫無廉恥心。", example: "他死皮賴臉地跟著她，令她很反感。" },
  { id: "s079", grade: 10, term: "吹牛皮", kind: "俚語", meaning: "說大話和夸大事實，吹噓自己的能力和成就。", example: "他喜歡吹牛皮，說自己能一個人打十個人。" },
  { id: "s080", grade: 11, term: "硬著頭皮", kind: "俚語", meaning: "明知有困難卻勉強自己去做，被迫不得不為之。", example: "他不想去參加那個活動，但硬著頭皮去了。" },
  // ---- 2026-08-02 擴充：s081-s160 ----
  // 諺語（28）
  { id: "s081", grade: 1, term: "早起的鳥兒有蟲吃", kind: "諺語", meaning: "勤快、搶先行動的人才能得到機會與收穫。", example: "早起的鳥兒有蟲吃，他總是第一個到教室複習功課。" },
  { id: "s082", grade: 1, term: "積少成多", kind: "諺語", meaning: "一點一滴累積，數量就會變多。", example: "每天存十元，積少成多，一年也能存下不少零用錢。" },
  { id: "s083", grade: 1, term: "有志者事竟成", kind: "諺語", meaning: "只要有決心毅力，事情終究會成功。", example: "有志者事竟成，他苦練兩年終於學會游泳。" },
  { id: "s084", grade: 2, term: "失敗為成功之母", kind: "諺語", meaning: "從失敗中記取教訓，才能走向成功。", example: "別怕做錯，失敗為成功之母，再試一次就好。" },
  { id: "s085", grade: 2, term: "種瓜得瓜，種豆得豆", kind: "諺語", meaning: "付出什麼樣的努力，就得到什麼樣的結果。", example: "種瓜得瓜，種豆得豆，平時偷懶考試自然吃虧。" },
  { id: "s086", grade: 2, term: "人外有人，天外有天", kind: "諺語", meaning: "強中更有強中手，不可自滿。", example: "他在校內是冠軍，到了全國賽才知道人外有人，天外有天。" },
  { id: "s087", grade: 3, term: "眼見為憑", kind: "諺語", meaning: "親眼看到的才算數，不輕信傳聞。", example: "網路傳言別急著轉發，眼見為憑，先查證再說。" },
  { id: "s088", grade: 3, term: "遠親不如近鄰", kind: "諺語", meaning: "住得近的鄰居，往往比遠方親戚更能及時幫忙。", example: "阿公跌倒是隔壁林太太送醫的，真是遠親不如近鄰。" },
  { id: "s089", grade: 3, term: "家和萬事興", kind: "諺語", meaning: "家庭和睦，一切事情才會興旺順利。", example: "爸爸常說家和萬事興，一家人有話好好講。" },
  { id: "s090", grade: 3, term: "病從口入，禍從口出", kind: "諺語", meaning: "亂吃東西會生病，亂說話會招來災禍。", example: "說話前先想想，病從口入，禍從口出。" },
  { id: "s091", grade: 4, term: "不入虎穴，焉得虎子", kind: "諺語", meaning: "不冒險進入險境，就得不到珍貴的成果。", example: "記者深入災區採訪，正是不入虎穴，焉得虎子。" },
  { id: "s092", grade: 4, term: "少壯不努力，老大徒傷悲", kind: "諺語", meaning: "年輕時不努力，年老時後悔也來不及。", example: "老師以「少壯不努力，老大徒傷悲」勉勵我們把握現在。" },
  { id: "s093", grade: 4, term: "讀萬卷書，行萬里路", kind: "諺語", meaning: "既要飽讀詩書，也要實地見聞，增廣見識。", example: "暑假全家環島，媽媽說這是讀萬卷書，行萬里路。" },
  { id: "s094", grade: 4, term: "前人種樹，後人乘涼", kind: "諺語", meaning: "前人辛勞打下基礎，後人得以享受成果。", example: "圖書館是校友捐建的，前人種樹，後人乘涼。" },
  { id: "s095", grade: 5, term: "一寸光陰一寸金，寸金難買寸光陰", kind: "諺語", meaning: "時間比黃金更寶貴，逝去便無法買回。", example: "考前衝刺要分秒必爭，一寸光陰一寸金，寸金難買寸光陰。" },
  { id: "s096", grade: 5, term: "三個臭皮匠，勝過一個諸葛亮", kind: "諺語", meaning: "眾人合力集思廣益，勝過一人獨自聰明。", example: "小組討論常有妙點子，三個臭皮匠，勝過一個諸葛亮。" },
  { id: "s097", grade: 5, term: "冰凍三尺，非一日之寒", kind: "諺語", meaning: "事情演變至此，是長期累積的結果。", example: "他倆的心結冰凍三尺，非一日之寒，得慢慢化解。" },
  { id: "s098", grade: 5, term: "樹大招風", kind: "諺語", meaning: "名聲地位太高，容易招人嫉妒攻擊。", example: "公司做大了難免樹大招風，行事更要謹慎。" },
  { id: "s099", grade: 6, term: "良藥苦口利於病", kind: "諺語", meaning: "有效的藥往往苦口，有益的規勸往往刺耳。", example: "教練的批評雖然難聽，但良藥苦口利於病。" },
  { id: "s100", grade: 6, term: "忠言逆耳利於行", kind: "諺語", meaning: "誠懇的勸告雖不中聽，卻對行事有幫助。", example: "他能接受忠言逆耳利於行，虛心改進缺點。" },
  { id: "s101", grade: 6, term: "青出於藍，更勝於藍", kind: "諺語", meaning: "學生勝過老師，後人超越前人。", example: "徒弟的手藝青出於藍，更勝於藍，師傅與有榮焉。" },
  { id: "s102", grade: 7, term: "玉不琢，不成器", kind: "諺語", meaning: "人不經過磨練教育，難以成材。", example: "嚴師出高徒，玉不琢，不成器。" },
  { id: "s103", grade: 7, term: "滿招損，謙受益", kind: "諺語", meaning: "自滿招致損失，謙虛獲得益處。", example: "得獎後他更加低調，深知滿招損，謙受益。" },
  { id: "s104", grade: 8, term: "水能載舟，亦能覆舟", kind: "諺語", meaning: "同一股力量能成就你，也能毀掉你；多喻民心向背。", example: "民意如流水，水能載舟，亦能覆舟。" },
  { id: "s105", grade: 8, term: "千里之堤，潰於蟻穴", kind: "諺語", meaning: "小疏忽不處理，會釀成大禍。", example: "小弊案不查，千里之堤，潰於蟻穴。" },
  { id: "s106", grade: 9, term: "人無遠慮，必有近憂", kind: "諺語", meaning: "沒有長遠打算，眼前很快就會出現麻煩。", example: "月光族要記住：人無遠慮，必有近憂。" },
  { id: "s107", grade: 9, term: "工欲善其事，必先利其器", kind: "諺語", meaning: "要把事情做好，先把工具準備好。", example: "工欲善其事，必先利其器，登山前先檢查裝備。" },
  { id: "s108", grade: 10, term: "學而不思則罔，思而不學則殆", kind: "諺語", meaning: "只讀書不思考會迷惘，只空想不讀書會危殆。", example: "唸書要邊讀邊想，學而不思則罔，思而不學則殆。" },
  // 台灣俗諺（俚語，25）
  { id: "s109", grade: 1, term: "愛拚才會贏", kind: "俚語", meaning: "台語俗諺：肯打拚努力，才會成功。", example: "阿爸常哼「愛拚才會贏」，鼓勵我們不要怕辛苦。" },
  { id: "s110", grade: 2, term: "大隻雞慢啼", kind: "俚語", meaning: "台語俗諺：大器晚成，有些人較晚才展現才能。", example: "他小學成績平平，高中突飛猛進，真是大隻雞慢啼。" },
  { id: "s111", grade: 2, term: "歹竹出好筍", kind: "俚語", meaning: "台語俗諺：平凡的環境也能培養出優秀的人才。", example: "他出身貧困卻考上醫學系，鄰居都說歹竹出好筍。" },
  { id: "s112", grade: 3, term: "一兼二顧，摸蜊仔兼洗褲", kind: "俚語", meaning: "台語俗諺：一次行動同時達成兩個目的。", example: "騎車送貨順路運動，一兼二顧，摸蜊仔兼洗褲。" },
  { id: "s113", grade: 3, term: "好酒沉甕底", kind: "俚語", meaning: "台語俗諺：好的東西往往留在最後才出現。", example: "壓軸表演最精采，果然好酒沉甕底。" },
  { id: "s114", grade: 3, term: "近廟欺神", kind: "俚語", meaning: "台語俗諺：對身邊熟悉的人事物反而不知珍惜敬重。", example: "住在故宮旁卻從沒進去參觀，真是近廟欺神。" },
  { id: "s115", grade: 4, term: "龜笑鱉無尾", kind: "俚語", meaning: "台語俗諺：自己也有同樣缺點，卻嘲笑別人。", example: "他字也寫得潦草還笑我，龜笑鱉無尾。" },
  { id: "s116", grade: 4, term: "輸人毋輸陣", kind: "俚語", meaning: "台語俗諺：個人可以輸，氣勢和場面不能輸。", example: "啦啦隊比賽大家卯足全力，輸人毋輸陣。" },
  { id: "s117", grade: 4, term: "呷人一口，報人一斗", kind: "俚語", meaning: "台語俗諺：受人一點恩惠，要加倍回報。", example: "當年受他幫助，如今呷人一口，報人一斗，理當相挺。" },
  { id: "s118", grade: 5, term: "細漢偷挽匏，大漢偷牽牛", kind: "俚語", meaning: "台語俗諺：小時偷小東西不糾正，長大會犯大錯。", example: "小錯要及時管教，免得細漢偷挽匏，大漢偷牽牛。" },
  { id: "s119", grade: 5, term: "三日無餾，爬上樹", kind: "俚語", meaning: "台語俗諺：學過的東西幾天不複習就生疏忘光。", example: "英文單字三日無餾，爬上樹，要天天複習。" },
  { id: "s120", grade: 5, term: "好天著存雨來糧", kind: "俚語", meaning: "台語俗諺：順境時要為逆境預作準備。", example: "景氣好時多存錢，好天著存雨來糧。" },
  { id: "s121", grade: 6, term: "樹頭徛予在，毋驚樹尾做風颱", kind: "俚語", meaning: "台語俗諺：根基站得穩，就不怕外來的風雨考驗。", example: "基本功練扎實，樹頭徛予在，毋驚樹尾做風颱。" },
  { id: "s122", grade: 6, term: "一暝全頭路，天光無半步", kind: "俚語", meaning: "台語俗諺：夜裡想了一堆計畫，天亮卻一樣也沒做。", example: "光說不練就是一暝全頭路，天光無半步。" },
  { id: "s123", grade: 6, term: "甘願做牛，免驚無犁通拖", kind: "俚語", meaning: "台語俗諺：肯吃苦做事，就不怕沒有工作機會。", example: "他什麼粗活都肯學，甘願做牛，免驚無犁通拖。" },
  { id: "s124", grade: 7, term: "做牛著拖，做人著磨", kind: "俚語", meaning: "台語俗諺：做人本來就要經歷磨練，吃苦是本分。", example: "阿嬤說做牛著拖，做人著磨，年輕多吃苦不是壞事。" },
  { id: "s125", grade: 7, term: "未食五日節粽，破裘毋甘放", kind: "俚語", meaning: "台語俗諺：端午節前天氣多變，冬衣還不能收起來。", example: "五月天忽冷忽熱，未食五日節粽，破裘毋甘放。" },
  { id: "s126", grade: 7, term: "嚴官府出厚賊", kind: "俚語", meaning: "台語俗諺：一味嚴刑峻罰，未必能遏止犯罪，反而更多。", example: "只罰不教，嚴官府出厚賊，問題依然存在。" },
  { id: "s127", grade: 8, term: "相罵無好話，相拍無揀位", kind: "俚語", meaning: "台語俗諺：吵架時口不擇言，打架時下手不知輕重。", example: "衝突要冷靜，相罵無好話，相拍無揀位，別造成遺憾。" },
  { id: "s128", grade: 8, term: "仙人拍鼓有時錯，跤步踏差啥人無", kind: "俚語", meaning: "台語俗諺：連神仙都會出錯，人犯錯在所難免，要寬容。", example: "他已道歉就原諒吧，仙人拍鼓有時錯，跤步踏差啥人無。" },
  { id: "s129", grade: 8, term: "燒瓷的食缺，織蓆的睏椅", kind: "俚語", meaning: "台語俗諺：製造好物的人自己反而用不到好東西。", example: "名廚回家常吃泡麵，燒瓷的食缺，織蓆的睏椅。" },
  { id: "s130", grade: 9, term: "拿香跟拜", kind: "俚語", meaning: "台語俗諺：沒有主見，別人做什麼就跟著做什麼。", example: "投資要有判斷，不要看別人買什麼就拿香跟拜。" },
  { id: "s131", grade: 9, term: "呷碗內，看碗外", kind: "俚語", meaning: "台語俗諺：吃著自己的，還貪圖別人的；吃裡扒外。", example: "領公司薪水卻幫對手做事，根本是呷碗內，看碗外。" },
  { id: "s132", grade: 9, term: "會曉偷食，袂曉拭喙", kind: "俚語", meaning: "台語俗諺：做了虧心事卻不會掩飾，留下把柄。", example: "他刪了紀錄卻忘了關代辦，會曉偷食，袂曉拭喙。" },
  { id: "s133", grade: 10, term: "戲棚跤徛久就是你的", kind: "俚語", meaning: "台語俗諺：肯堅持等待、蹲點耕耘的人終會得到機會。", example: "跑龍套十年終於當上主角，戲棚跤徛久就是你的。" },
  // 歇後語（27）
  { id: "s134", grade: 2, term: "啞巴吃黃連——有苦說不出", kind: "歇後語", meaning: "心裡有苦處，卻無法對人訴說。", example: "被誤會又不能解釋，他真是啞巴吃黃連——有苦說不出。" },
  { id: "s135", grade: 2, term: "肉包子打狗——有去無回", kind: "歇後語", meaning: "東西送出去就再也要不回來。", example: "借錢給他就像肉包子打狗——有去無回。" },
  { id: "s136", grade: 2, term: "熱鍋上的螞蟻——團團轉", kind: "歇後語", meaning: "焦急慌張，走來走去不知如何是好。", example: "找不到門票，他急得像熱鍋上的螞蟻——團團轉。" },
  { id: "s137", grade: 3, term: "貓哭耗子——假慈悲", kind: "歇後語", meaning: "假裝同情憐憫，其實心懷鬼胎。", example: "平時欺負人，現在來慰問？貓哭耗子——假慈悲。" },
  { id: "s138", grade: 3, term: "千里送鵝毛——禮輕情意重", kind: "歇後語", meaning: "禮物雖輕，情意卻深厚。", example: "這張手寫卡片是千里送鵝毛——禮輕情意重。" },
  { id: "s139", grade: 3, term: "芝麻開花——節節高", kind: "歇後語", meaning: "情況一節比一節好，不斷進步。", example: "小店生意芝麻開花——節節高，準備開分店了。" },
  { id: "s140", grade: 3, term: "兔子尾巴——長不了", kind: "歇後語", meaning: "形容事物維持不了多久。", example: "靠炒作的名氣是兔子尾巴——長不了。" },
  { id: "s141", grade: 4, term: "王婆賣瓜——自賣自誇", kind: "歇後語", meaning: "自己誇耀自己的東西好。", example: "他猛稱讚自家產品，王婆賣瓜——自賣自誇。" },
  { id: "s142", grade: 4, term: "姜太公釣魚——願者上鉤", kind: "歇後語", meaning: "心甘情願地上當或參與，怨不得別人。", example: "這種高價課程，姜太公釣魚——願者上鉤。" },
  { id: "s143", grade: 4, term: "啞巴吃湯圓——心裡有數", kind: "歇後語", meaning: "嘴上不說，心裡清楚得很。", example: "誰出多少力，大家啞巴吃湯圓——心裡有數。" },
  { id: "s144", grade: 4, term: "猴子撈月——一場空", kind: "歇後語", meaning: "白忙一場，什麼也得不到。", example: "跟風搶購虛擬幣，最後猴子撈月——一場空。" },
  { id: "s145", grade: 5, term: "外甥打燈籠——照舊（舅）", kind: "歇後語", meaning: "諧音雙關：一切照老樣子，沒有改變。", example: "說要改革，結果外甥打燈籠——照舊。" },
  { id: "s146", grade: 5, term: "孔夫子搬家——盡是書（輸）", kind: "歇後語", meaning: "諧音雙關：一直輸，沒贏過。", example: "這支隊伍本季孔夫子搬家——盡是書（輸）。" },
  { id: "s147", grade: 5, term: "門縫裡看人——把人看扁了", kind: "歇後語", meaning: "小看、輕視別人。", example: "說我不行？你這是門縫裡看人——把人看扁了。" },
  { id: "s148", grade: 5, term: "小蔥拌豆腐——一清二白", kind: "歇後語", meaning: "清清楚楚，毫無瓜葛污點。", example: "帳目攤開檢查，小蔥拌豆腐——一清二白。" },
  { id: "s149", grade: 6, term: "秀才遇到兵——有理說不清", kind: "歇後語", meaning: "對不講道理的人，再有道理也講不通。", example: "跟蠻橫的人爭辯，秀才遇到兵——有理說不清。" },
  { id: "s150", grade: 6, term: "和尚打傘——無法（髮）無天", kind: "歇後語", meaning: "諧音雙關：目無法紀，胡作非為。", example: "飆車族深夜橫行，簡直和尚打傘——無法無天。" },
  { id: "s151", grade: 6, term: "泥牛入海——無消息", kind: "歇後語", meaning: "一去不回，音訊全無。", example: "履歷投出去像泥牛入海——無消息。" },
  { id: "s152", grade: 6, term: "飛蛾撲火——自取滅亡", kind: "歇後語", meaning: "自己往危險裡衝，自尋死路。", example: "明知是詐騙還把錢匯過去，飛蛾撲火——自取滅亡。" },
  { id: "s153", grade: 7, term: "周瑜打黃蓋——一個願打，一個願挨", kind: "歇後語", meaning: "雙方你情我願，旁人管不著。", example: "加價搶演唱會票，周瑜打黃蓋——一個願打，一個願挨。" },
  { id: "s154", grade: 7, term: "韓信點兵——多多益善", kind: "歇後語", meaning: "越多越好。", example: "備援物資韓信點兵——多多益善。" },
  { id: "s155", grade: 7, term: "豬八戒照鏡子——裡外不是人", kind: "歇後語", meaning: "兩面都得罪，兩頭不討好。", example: "夾在婆媳之間，他豬八戒照鏡子——裡外不是人。" },
  { id: "s156", grade: 8, term: "大水沖倒龍王廟——自家人不認自家人", kind: "歇後語", meaning: "自己人之間起了衝突誤會。", example: "兩個部門搶功勞，大水沖倒龍王廟——自家人不認自家人。" },
  { id: "s157", grade: 8, term: "司馬昭之心——路人皆知", kind: "歇後語", meaning: "野心陰謀十分明顯，人人都看得出來。", example: "他處處布局搶位子，司馬昭之心——路人皆知。" },
  { id: "s158", grade: 8, term: "電線桿上綁雞毛——好大的撢（膽）子", kind: "歇後語", meaning: "諧音雙關：膽子真大。", example: "敢偽造公文？電線桿上綁雞毛——好大的膽子。" },
  { id: "s159", grade: 9, term: "擀麵杖吹火——一竅不通", kind: "歇後語", meaning: "比喻對某事完全不懂。", example: "說到程式設計，我是擀麵杖吹火——一竅不通。" },
  { id: "s160", grade: 9, term: "周處除三害——自新之路", kind: "歇後語", meaning: "改過向善，重新做人。", example: "他出獄後創業助人，走上周處除三害——自新之路。" },
  // ---- 2026-08-02 三輪擴充:s161-s240 ----
  // 諺語(30)
  { id: "s161", grade: 1, term: "吃得苦中苦，方為人上人", kind: "諺語", meaning: "能忍受艱苦磨練的人，才能出人頭地。", example: "阿公常說吃得苦中苦，方為人上人，勉勵我們別怕辛苦。" },
  { id: "s162", grade: 1, term: "萬丈高樓平地起", kind: "諺語", meaning: "再大的成就也要從基礎開始。", example: "先把注音學好，萬丈高樓平地起。" },
  { id: "s163", grade: 2, term: "好的開始是成功的一半", kind: "諺語", meaning: "開頭做得好，成功就有了一半把握。", example: "第一週就養成寫作業的習慣，好的開始是成功的一半。" },
  { id: "s164", grade: 2, term: "戲棚下站久就是你的", kind: "諺語", meaning: "堅持等待、持續耕耘的人終能得到機會。", example: "他跑了五年龍套終於當上主角，戲棚下站久就是你的。" },
  { id: "s165", grade: 2, term: "一回生，二回熟", kind: "諺語", meaning: "第一次陌生，第二次就熟練了。", example: "上台別緊張，一回生，二回熟。" },
  { id: "s166", grade: 3, term: "師父領進門，修行在個人", kind: "諺語", meaning: "老師只能引導，成就要靠自己努力。", example: "補習只是輔助，師父領進門，修行在個人。" },
  { id: "s167", grade: 3, term: "台上一分鐘，台下十年功", kind: "諺語", meaning: "精彩的演出背後是長年的苦練。", example: "特技演員台上一分鐘，台下十年功。" },
  { id: "s168", grade: 3, term: "眾人拾柴火焰高", kind: "諺語", meaning: "人多力量大，共同努力成效更好。", example: "義賣募款眾人拾柴火焰高，很快達標。" },
  { id: "s169", grade: 3, term: "遠水救不了近火", kind: "諺語", meaning: "緩慢的辦法解決不了眼前的急難。", example: "調貨要一週，遠水救不了近火，先跟鄰店借吧。" },
  { id: "s170", grade: 4, term: "不經一事，不長一智", kind: "諺語", meaning: "沒有經歷過就不會增長見識。", example: "被騙過一次才學會查證，不經一事，不長一智。" },
  { id: "s171", grade: 4, term: "吃一塹，長一智", kind: "諺語", meaning: "受一次挫折，長一分見識。", example: "投資失利後他學會分散風險，吃一塹，長一智。" },
  { id: "s172", grade: 4, term: "當局者迷，旁觀者清", kind: "諺語", meaning: "當事人容易迷惑，旁觀的人反而看得清楚。", example: "你先聽聽別人怎麼看，當局者迷，旁觀者清。" },
  { id: "s173", grade: 4, term: "禮多人不怪", kind: "諺語", meaning: "多行禮數不會惹人厭。", example: "進門先問好，禮多人不怪。" },
  { id: "s174", grade: 4, term: "和氣生財", kind: "諺語", meaning: "待人和氣才能招來生意與福氣。", example: "老闆娘總是笑臉迎人，和氣生財。" },
  { id: "s175", grade: 5, term: "路是人走出來的", kind: "諺語", meaning: "方法和機會靠人開創。", example: "沒有前例就自己開先例，路是人走出來的。" },
  { id: "s176", grade: 5, term: "船到橋頭自然直", kind: "諺語", meaning: "事情到了關頭自有辦法解決，不必過度擔憂。", example: "先盡力準備，其他的船到橋頭自然直。" },
  { id: "s177", grade: 5, term: "人算不如天算", kind: "諺語", meaning: "人的謀劃敵不過情勢的變化。", example: "行程排好卻遇颱風，人算不如天算。" },
  { id: "s178", grade: 5, term: "謀事在人，成事在天", kind: "諺語", meaning: "盡力籌劃是人的本分，成敗還受環境影響。", example: "把能做的做好，謀事在人，成事在天。" },
  { id: "s179", grade: 5, term: "強將手下無弱兵", kind: "諺語", meaning: "能幹的領導者帶出來的部屬也不差。", example: "冠軍教頭的子弟兵個個出色，強將手下無弱兵。" },
  { id: "s180", grade: 5, term: "嚴師出高徒", kind: "諺語", meaning: "要求嚴格的老師能教出優秀的學生。", example: "他的老師出了名的嚴，嚴師出高徒。" },
  { id: "s181", grade: 6, term: "玉不琢，不成器；人不學，不知義", kind: "諺語", meaning: "玉要雕琢才成器，人要學習才明理。", example: "爸爸用「玉不琢，不成器」勉勵我認真上課。" },
  { id: "s182", grade: 6, term: "一樣米養百樣人", kind: "諺語", meaning: "同樣的環境養出各種不同性格的人。", example: "同班同學個性天差地遠，一樣米養百樣人。" },
  { id: "s183", grade: 6, term: "遠親不如近鄰，近鄰不如對門", kind: "諺語", meaning: "住得越近的人越能及時互相照應。", example: "對門阿姨常幫忙收包裹，遠親不如近鄰，近鄰不如對門。" },
  { id: "s184", grade: 6, term: "貨比三家不吃虧", kind: "諺語", meaning: "多比較再購買才不會吃虧。", example: "買手機前他貨比三家不吃虧，省了兩千元。" },
  { id: "s185", grade: 7, term: "醉翁之意不在酒", kind: "諺語", meaning: "表面做一件事，真正目的在別處。", example: "他頻頻來請教功課，醉翁之意不在酒，是想約妹妹打球。" },
  { id: "s186", grade: 7, term: "近水樓臺先得月", kind: "諺語", meaning: "接近有利環境的人先獲得好處。", example: "住學校旁的他天天泡圖書館，近水樓臺先得月。" },
  { id: "s187", grade: 8, term: "初生之犢不畏虎", kind: "諺語", meaning: "年輕人沒有顧忌，敢做敢衝。", example: "高一新生敢挑戰學長，初生之犢不畏虎。" },
  { id: "s188", grade: 8, term: "薑是老的辣", kind: "諺語", meaning: "年長者經驗豐富，手段更高明。", example: "老師傅一出手就解決問題，薑是老的辣。" },
  { id: "s189", grade: 9, term: "士別三日，刮目相看", kind: "諺語", meaning: "人會進步，過些時候要用新眼光看待。", example: "半年不見他英文突飛猛進，士別三日，刮目相看。" },
  { id: "s190", grade: 9, term: "青出於藍而勝於藍", kind: "諺語", meaning: "弟子勝過老師，後人超越前人。", example: "徒弟的雕工更勝師父，青出於藍而勝於藍。" },
  // 台灣俗諺(俚語,25)
  { id: "s191", grade: 1, term: "食果子拜樹頭", kind: "俚語", meaning: "台語俗諺:吃果子要感謝果樹，比喻懂得感恩。", example: "領獎時他感謝啟蒙教練，食果子拜樹頭。" },
  { id: "s192", grade: 2, term: "一枝草，一點露", kind: "俚語", meaning: "台語俗諺:天無絕人之路，各有生路。", example: "別擔心畢業找不到頭路，一枝草，一點露。" },
  { id: "s193", grade: 2, term: "細漢毋通看無", kind: "俚語", meaning: "台語俗諺:不要小看年紀小或勢力小的人。", example: "學弟球速驚人，細漢毋通看無。" },
  { id: "s194", grade: 3, term: "人兩腳，錢四腳", kind: "俚語", meaning: "台語俗諺:錢難追，人追錢追不上，勸人腳踏實地。", example: "別想一夜致富，人兩腳，錢四腳。" },
  { id: "s195", grade: 3, term: "第一憨，種甘蔗予會社磅", kind: "俚語", meaning: "台語俗諺:譏諷吃虧還任人擺布的傻事。", example: "簽這種不平等契約，是第一憨，種甘蔗予會社磅。" },
  { id: "s196", grade: 3, term: "有樣看樣，無樣家己想", kind: "俚語", meaning: "台語俗諺:有榜樣就學，沒有就自己動腦。", example: "創業沒人帶，有樣看樣，無樣家己想。" },
  { id: "s197", grade: 4, term: "緊事寬辦", kind: "俚語", meaning: "台語俗諺:越急的事越要沉著處理。", example: "越到截止日越要緊事寬辦，才不會出錯。" },
  { id: "s198", grade: 4, term: "呷飯皇帝大", kind: "俚語", meaning: "台語俗諺:吃飯時最大，什麼事都先擱下。", example: "先讓工人吃飽再談公事，呷飯皇帝大。" },
  { id: "s199", grade: 4, term: "歹戲拖棚", kind: "俚語", meaning: "台語俗諺:難看的戲偏偏拖得長，事情糟又拖延。", example: "這場糾紛歹戲拖棚，吵了半年沒結果。" },
  { id: "s200", grade: 4, term: "生食都無夠，閣有通曝乾", kind: "俚語", meaning: "台語俗諺:現吃都不夠了，哪還有得晒乾存起來。", example: "薪水月月見底，生食都無夠，閣有通曝乾？" },
  { id: "s201", grade: 5, term: "頂司管下司，鋤頭管畚箕", kind: "俚語", meaning: "台語俗諺:層層節制，一物剋一物。", example: "公司層級分明，頂司管下司，鋤頭管畚箕。" },
  { id: "s202", grade: 5, term: "做著歹田望後冬", kind: "俚語", meaning: "台語俗諺:這次收成不好，寄望下一季，永保希望。", example: "今年業績差，做著歹田望後冬，明年再拚。" },
  { id: "s203", grade: 5, term: "一個錢，拍二十四個結", kind: "俚語", meaning: "台語俗諺:形容人極度節儉、捨不得花錢。", example: "阿伯一個錢拍二十四個結，省出三間房。" },
  { id: "s204", grade: 5, term: "軟土深掘", kind: "俚語", meaning: "台語俗諺:欺負好說話的人，得寸進尺。", example: "他越客氣對方越過分，真是軟土深掘。" },
  { id: "s205", grade: 6, term: "臺灣錢，淹跤目", kind: "俚語", meaning: "台語俗諺:形容早年台灣經濟繁榮、賺錢容易。", example: "八〇年代臺灣錢淹跤目，工廠訂單接不完。" },
  { id: "s206", grade: 6, term: "緊紡無好紗，緊嫁無好大家", kind: "俚語", meaning: "台語俗諺:倉促行事難有好結果。", example: "求快犧牲品質，緊紡無好紗，緊嫁無好大家。" },
  { id: "s207", grade: 6, term: "無魚，蝦嘛好", kind: "俚語", meaning: "台語俗諺:退而求其次，有總比沒有好。", example: "搶不到演唱會門票，看轉播無魚蝦嘛好。" },
  { id: "s208", grade: 6, term: "驚驚袂著等", kind: "俚語", meaning: "台語俗諺:畏縮膽怯就得不到獎賞，要勇於嘗試。", example: "想告白就去，驚驚袂著等。" },
  { id: "s209", grade: 7, term: "醜醜馬嘛有一步踢", kind: "俚語", meaning: "台語俗諺:再平凡的人也有一技之長。", example: "別小看他，醜醜馬嘛有一步踢。" },
  { id: "s210", grade: 7, term: "紅媠，烏大範", kind: "俚語", meaning: "台語俗諺:紅色亮麗、黑色大方，各有各的美。", example: "選制服顏色時奶奶說紅媠烏大範，都好看。" },
  { id: "s211", grade: 7, term: "樹頭徛予在", kind: "俚語", meaning: "台語俗諺:根基要站得穩(常接「毋驚樹尾做風颱」)。", example: "基本功是樹頭，樹頭徛予在，才禁得起考驗。" },
  { id: "s212", grade: 8, term: "掠龜走鱉", kind: "俚語", meaning: "台語俗諺:顧了這頭丟了那頭，兩頭落空。", example: "同時追兩個案子結果掠龜走鱉，都沒成。" },
  { id: "s213", grade: 8, term: "乞食趕廟公", kind: "俚語", meaning: "台語俗諺:反客為主，受人恩惠反而喧賓奪主。", example: "借住還嫌東嫌西，乞食趕廟公。" },
  { id: "s214", grade: 9, term: "毋通食碗內，說碗外", kind: "俚語", meaning: "台語俗諺:不要吃裡扒外。", example: "領公司薪水就別幫對手說話，毋通食碗內說碗外。" },
  { id: "s215", grade: 9, term: "戲好看，鑼鼓聲了就散", kind: "俚語", meaning: "台語俗諺:熱鬧終有曲終人散時。", example: "慶功宴再熱鬧，戲好看，鑼鼓聲了就散。" },
  // 歇後語(25)
  { id: "s216", grade: 2, term: "小和尚念經──有口無心", kind: "歇後語", meaning: "嘴上說著，心裡並不在意。", example: "他道歉像小和尚念經──有口無心。" },
  { id: "s217", grade: 2, term: "貓咬尿泡──空歡喜", kind: "歇後語", meaning: "白高興一場。", example: "中獎簡訊是詐騙，貓咬尿泡──空歡喜。" },
  { id: "s218", grade: 3, term: "啞巴見媽媽──沒說的", kind: "歇後語", meaning: "好得沒話說。", example: "這家滷肉飯的味道，啞巴見媽媽──沒說的。" },
  { id: "s219", grade: 3, term: "豬鼻子插蔥──裝象", kind: "歇後語", meaning: "諧音雙關:假裝了不起。", example: "租名車擺闊，豬鼻子插蔥──裝象。" },
  { id: "s220", grade: 3, term: "老鼠過街──人人喊打", kind: "歇後語", meaning: "作惡者人人痛恨。", example: "詐騙集團如老鼠過街──人人喊打。" },
  { id: "s221", grade: 4, term: "谷底彈簧──觸底反彈", kind: "歇後語", meaning: "跌到最低點後開始好轉。", example: "球隊戰績谷底彈簧──觸底反彈，五連勝。" },
  { id: "s222", grade: 4, term: "鴨子聽雷──有聽沒有懂", kind: "歇後語", meaning: "完全聽不懂。", example: "第一次聽微積分，我鴨子聽雷──有聽沒有懂。" },
  { id: "s223", grade: 4, term: "斷了線的風箏──身不由己", kind: "歇後語", meaning: "失去依靠，無法自主。", example: "被浪潮推著走，像斷了線的風箏──身不由己。" },
  { id: "s224", grade: 4, term: "電風扇吹雞毛──亂了套", kind: "歇後語", meaning: "秩序大亂。", example: "臨時換場地，流程電風扇吹雞毛──亂了套。" },
  { id: "s225", grade: 5, term: "劉備借荊州──有借無還", kind: "歇後語", meaning: "借了就不歸還。", example: "他借書向來劉備借荊州──有借無還。" },
  { id: "s226", grade: 5, term: "徐庶進曹營──一言不發", kind: "歇後語", meaning: "始終沉默不表態。", example: "整場會議他徐庶進曹營──一言不發。" },
  { id: "s227", grade: 5, term: "張飛穿針──大眼瞪小眼", kind: "歇後語", meaning: "彼此對望，無計可施。", example: "停電後全家張飛穿針──大眼瞪小眼。" },
  { id: "s228", grade: 5, term: "諸葛亮借東風──神機妙算", kind: "歇後語", meaning: "謀劃精準高明。", example: "他提前備貨躲過缺料潮，諸葛亮借東風──神機妙算。" },
  { id: "s229", grade: 6, term: "關公面前耍大刀──不自量力", kind: "歇後語", meaning: "在行家面前賣弄本領。", example: "跟國手比球速？關公面前耍大刀──不自量力。" },
  { id: "s230", grade: 6, term: "包公斷案──鐵面無私", kind: "歇後語", meaning: "執法公正，不講情面。", example: "風紀股長包公斷案──鐵面無私。" },
  { id: "s231", grade: 6, term: "半路殺出個程咬金──出人意料", kind: "歇後語", meaning: "突然出現意想不到的人或事。", example: "眼看要成交，半路殺出個程咬金──出人意料。" },
  { id: "s232", grade: 6, term: "孫悟空七十二變──神通廣大", kind: "歇後語", meaning: "本領高強，變化多端。", example: "這位特效師孫悟空七十二變──神通廣大。" },
  { id: "s233", grade: 7, term: "豬八戒吃人參果──全不知滋味", kind: "歇後語", meaning: "囫圇享用，不懂品味。", example: "名茶牛飲而盡，豬八戒吃人參果──全不知滋味。" },
  { id: "s234", grade: 7, term: "王小二過年──一年不如一年", kind: "歇後語", meaning: "情況一年比一年差。", example: "老街生意王小二過年──一年不如一年。" },
  { id: "s235", grade: 7, term: "麻雀雖小──五臟俱全", kind: "歇後語", meaning: "規模雖小，該有的都有。", example: "這間套房麻雀雖小──五臟俱全。" },
  { id: "s236", grade: 8, term: "螃蟹過馬路──橫行霸道", kind: "歇後語", meaning: "仗勢橫行，不講道理。", example: "惡少在夜市螃蟹過馬路──橫行霸道。" },
  { id: "s237", grade: 8, term: "禿子頭上的蝨子──明擺著", kind: "歇後語", meaning: "事情明顯，一目了然。", example: "誰在搗鬼？禿子頭上的蝨子──明擺著。" },
  { id: "s238", grade: 8, term: "太歲頭上動土──膽子不小", kind: "歇後語", meaning: "敢冒犯有權勢的人。", example: "敢檢舉黑心大戶，真是太歲頭上動土──膽子不小。" },
  { id: "s239", grade: 9, term: "周瑜謀荊州──賠了夫人又折兵", kind: "歇後語", meaning: "想占便宜反而雙重損失。", example: "挖角不成還洩了底牌，賠了夫人又折兵。" },
  { id: "s240", grade: 9, term: "姜子牙釣魚──離水三寸", kind: "歇後語", meaning: "不合常規，別有用意。", example: "他開的條件姜子牙釣魚──離水三寸，等識貨的人。" },
  // ---- s241-s320 ----
  // 諺語(30)
  { id: "s241", grade: 1, term: "在家靠父母，出外靠朋友", kind: "諺語", meaning: "在外闖蕩需要朋友互相扶持。", example: "第一次北上工作，深深體會在家靠父母，出外靠朋友。" },
  { id: "s242", grade: 1, term: "笑一笑，十年少", kind: "諺語", meaning: "保持愉快心情使人年輕健康。", example: "爺爺天天說笑話，笑一笑，十年少。" },
  { id: "s243", grade: 2, term: "日行一善", kind: "諺語", meaning: "每天做一件好事。", example: "班上推行日行一善，大家搶著服務。" },
  { id: "s244", grade: 2, term: "誠實為上策", kind: "諺語", meaning: "誠實是最好的做法。", example: "打破杯子就承認，誠實為上策。" },
  { id: "s245", grade: 2, term: "滿瓶水不響，半瓶水響叮噹", kind: "諺語", meaning: "有真才實學的人謙虛，一知半解的人愛炫耀。", example: "他懂最多卻最安靜，滿瓶水不響，半瓶水響叮噹。" },
  { id: "s246", grade: 3, term: "人要衣裝，佛要金裝", kind: "諺語", meaning: "適當的打扮能提升形象。", example: "面試前買套正式服裝，人要衣裝，佛要金裝。" },
  { id: "s247", grade: 3, term: "健康是最大的財富", kind: "諺語", meaning: "健康比金錢更寶貴。", example: "爸爸開始運動後常說健康是最大的財富。" },
  { id: "s248", grade: 3, term: "早睡早起身體好", kind: "諺語", meaning: "規律作息有益健康。", example: "想長高就要早睡早起身體好。" },
  { id: "s249", grade: 3, term: "飯後百步走，活到九十九", kind: "諺語", meaning: "飯後散步有益長壽健康。", example: "爺爺奉行飯後百步走，活到九十九。" },
  { id: "s250", grade: 4, term: "一言既出，駟馬難追", kind: "諺語", meaning: "話說出口就要守信，無法收回。", example: "答應的事要做到，一言既出，駟馬難追。" },
  { id: "s251", grade: 4, term: "君子一言，快馬一鞭", kind: "諺語", meaning: "說話算話，乾脆守信。", example: "他答應贊助就立刻匯款，君子一言，快馬一鞭。" },
  { id: "s252", grade: 4, term: "人非聖賢，孰能無過", kind: "諺語", meaning: "人都會犯錯，貴在能改。", example: "別太苛責他，人非聖賢，孰能無過。" },
  { id: "s253", grade: 4, term: "知錯能改，善莫大焉", kind: "諺語", meaning: "知道錯誤而能改正，是最大的善。", example: "他公開道歉並補救，知錯能改，善莫大焉。" },
  { id: "s254", grade: 4, term: "得饒人處且饒人", kind: "諺語", meaning: "能寬容的時候就寬容別人。", example: "他已認錯，得饒人處且饒人吧。" },
  { id: "s255", grade: 5, term: "退一步海闊天空", kind: "諺語", meaning: "讓步能使局面豁然開朗。", example: "爭到底兩敗俱傷，退一步海闊天空。" },
  { id: "s256", grade: 5, term: "忍一時風平浪靜", kind: "諺語", meaning: "暫時忍耐能平息衝突。", example: "他深呼吸不回嘴，忍一時風平浪靜。" },
  { id: "s257", grade: 5, term: "冤家宜解不宜結", kind: "諺語", meaning: "仇怨應該化解，不要結下。", example: "同行何必互告？冤家宜解不宜結。" },
  { id: "s258", grade: 5, term: "各人自掃門前雪", kind: "諺語", meaning: "只管自己的事，不管別人（多含批評自私之意）。", example: "社區事務沒人理，大家各人自掃門前雪。" },
  { id: "s259", grade: 5, term: "獨木不成林", kind: "諺語", meaning: "單獨一人成不了大事。", example: "再強的球星也要隊友，獨木不成林。" },
  { id: "s260", grade: 5, term: "人多好辦事", kind: "諺語", meaning: "人手多，事情容易辦成。", example: "全班分工佈置會場，人多好辦事。" },
  { id: "s261", grade: 6, term: "先小人後君子", kind: "諺語", meaning: "先把條件講清楚，之後好維持交情。", example: "合夥前先簽約，先小人後君子。" },
  { id: "s262", grade: 6, term: "親兄弟明算帳", kind: "諺語", meaning: "再親近的人金錢也要算清楚。", example: "合買房子也要親兄弟明算帳。" },
  { id: "s263", grade: 6, term: "便宜沒好貨", kind: "諺語", meaning: "價格過低的東西品質通常不佳。", example: "夜市三百元的「名牌」錶，便宜沒好貨。" },
  { id: "s264", grade: 6, term: "一分錢一分貨", kind: "諺語", meaning: "價格與品質相當。", example: "這雙鞋貴但耐穿，一分錢一分貨。" },
  { id: "s265", grade: 7, term: "羊毛出在羊身上", kind: "諺語", meaning: "表面的好處其實還是由自己付出。", example: "滿額贈其實羊毛出在羊身上。" },
  { id: "s266", grade: 7, term: "天下沒有白吃的午餐", kind: "諺語", meaning: "任何好處都要付出代價。", example: "高報酬必有高風險，天下沒有白吃的午餐。" },
  { id: "s267", grade: 7, term: "偷雞不著蝕把米", kind: "諺語", meaning: "想占便宜反而受損失。", example: "逃票被罰五十倍，偷雞不著蝕把米。" },
  { id: "s268", grade: 8, term: "螳螂捕蟬，黃雀在後", kind: "諺語", meaning: "只顧眼前利益，不知禍患將至。", example: "他忙著併購對手，卻不知螳螂捕蟬，黃雀在後。" },
  { id: "s269", grade: 8, term: "鷸蚌相爭，漁翁得利", kind: "諺語", meaning: "雙方相爭，第三者得利。", example: "兩強互槓，第三品牌鷸蚌相爭，漁翁得利。" },
  { id: "s270", grade: 9, term: "成也蕭何，敗也蕭何", kind: "諺語", meaning: "成敗都由同一人或同一因素造成。", example: "靠流量爆紅也因流量翻車，成也蕭何，敗也蕭何。" },
  // 台灣俗諺(俚語,25)
  { id: "s271", grade: 1, term: "囡仔人有耳無喙", kind: "俚語", meaning: "台語俗諺:小孩子只聽不插嘴（長輩告誡語）。", example: "大人談正事，阿嬤說囡仔人有耳無喙。" },
  { id: "s272", grade: 2, term: "囡仔人跳過溝，三碗飯落腹肚", kind: "俚語", meaning: "台語俗諺:小孩活動量大、食量驚人。", example: "弟弟跑一下午吃三碗飯，囡仔人跳過溝，三碗飯落腹肚。" },
  { id: "s273", grade: 2, term: "細粒子，好豆油", kind: "俚語", meaning: "台語俗諺:個子小卻精明能幹（如小瓶醬油更醇）。", example: "她個子嬌小卻扛下全場，細粒子，好豆油。" },
  { id: "s274", grade: 3, term: "做雞著筅，做人著反", kind: "俚語", meaning: "台語俗諺:雞要扒土找食，人要勤奮翻身。", example: "阿公說做雞著筅，做人著反，不能懶散。" },
  { id: "s275", grade: 3, term: "一皮天下無難事", kind: "俚語", meaning: "俗諺:臉皮厚就什麼都不怕（含戲謔）。", example: "他到處推銷不怕拒絕，一皮天下無難事。" },
  { id: "s276", grade: 3, term: "南風轉北，落雨袂停", kind: "俚語", meaning: "台語氣象俗諺:風向轉變預示天氣變化。", example: "阿公看天說南風轉北，落雨袂停，要帶傘。" },
  { id: "s277", grade: 4, term: "六月芥菜──假有心", kind: "俚語", meaning: "台語歇後式俗諺:六月的芥菜不結心，譏人假情假意。", example: "他那句慰問是六月芥菜──假有心。" },
  { id: "s278", grade: 4, term: "拚生拚死，毋值拄好時", kind: "俚語", meaning: "台語俗諺:拚命努力，也要碰上好時機。", example: "創業拚生拚死，毋值拄好時，也要看景氣。" },
  { id: "s279", grade: 4, term: "三分天注定，七分靠打拚", kind: "俚語", meaning: "台語俗諺:命運小部分天定，大部分靠努力。", example: "他常唱三分天注定，七分靠打拚勉勵自己。" },
  { id: "s280", grade: 4, term: "少年袂曉想，食老毋成樣", kind: "俚語", meaning: "台語俗諺:年輕不懂打算，年老就狼狽。", example: "月光族要警惕:少年袂曉想，食老毋成樣。" },
  { id: "s281", grade: 5, term: "會呼雞袂歕火", kind: "俚語", meaning: "台語俗諺:形容累到只剩喚雞的力氣，連吹火都沒力。", example: "搬完家具，我會呼雞袂歕火，癱在沙發上。" },
  { id: "s282", grade: 5, term: "人情留一線，日後好相看", kind: "俚語", meaning: "台語俗諺:做事留餘地，日後好相處。", example: "談判別趕盡殺絕，人情留一線，日後好相看。" },
  { id: "s283", grade: 5, term: "好嘴大富貴", kind: "俚語", meaning: "台語俗諺:嘴甜有禮帶來好人緣好運氣。", example: "他見人就問好，好嘴大富貴，客源不斷。" },
  { id: "s284", grade: 5, term: "一日剃頭，三日緣投", kind: "俚語", meaning: "台語俗諺:理完髮精神好幾天，打理儀容使人有精神。", example: "面試前去理髮，一日剃頭，三日緣投。" },
  { id: "s285", grade: 6, term: "千金買厝，萬金買厝邊", kind: "俚語", meaning: "台語俗諺:好鄰居比房子本身更珍貴。", example: "選這社區是因為鄰居好，千金買厝，萬金買厝邊。" },
  { id: "s286", grade: 6, term: "尪某同心，烏土變黃金", kind: "俚語", meaning: "台語俗諺:夫妻同心，泥土也能變黃金。", example: "夫妻擺攤二十年買下店面，尪某同心，烏土變黃金。" },
  { id: "s287", grade: 6, term: "序大無好樣，序細討和尚", kind: "俚語", meaning: "台語俗諺:長輩沒做好榜樣，晚輩就有樣學樣變壞。", example: "在孩子面前別滑手機滑整天，序大無好樣，序細討和尚。" },
  { id: "s288", grade: 7, term: "嚴父出孝子，慈母多敗兒", kind: "俚語", meaning: "俗諺:管教嚴格才能成材，過度溺愛反害了孩子。", example: "他感謝父親當年嚴格，嚴父出孝子。" },
  { id: "s289", grade: 7, term: "枵鬼假細膩", kind: "俚語", meaning: "台語俗諺:明明很想要卻假裝客氣。", example: "說不餓卻一直看蛋糕，枵鬼假細膩。" },
  { id: "s290", grade: 7, term: "緊行無好步", kind: "俚語", meaning: "台語俗諺:走得太急就沒有穩妥的步伐。", example: "決策別倉促，緊行無好步。" },
  { id: "s291", grade: 8, term: "青暝的毋驚銃", kind: "俚語", meaning: "台語俗諺:盲者不怕槍，無知者無所畏懼。", example: "新手敢梭哈全押，青暝的毋驚銃。" },
  { id: "s292", grade: 8, term: "貪字貧字殼", kind: "俚語", meaning: "台語俗諺:「貪」字是「貧」字的外殼，貪心導致貧窮。", example: "想一夜翻本結果輸光，貪字貧字殼。" },
  { id: "s293", grade: 8, term: "時到時擔當，無米才煮番薯湯", kind: "俚語", meaning: "台語俗諺:事到臨頭再想辦法，總有應變之道。", example: "先別焦慮，時到時擔當，無米才煮番薯湯。" },
  { id: "s294", grade: 9, term: "未食著肉，先食著湯", kind: "俚語", meaning: "台語俗諺:還沒得到主要好處，先嘗到附帶利益。", example: "案子還沒簽，先賺到名聲，未食著肉，先食著湯。" },
  { id: "s295", grade: 9, term: "毋驚虎生三個喙，只驚人懷雙樣心", kind: "俚語", meaning: "台語俗諺:不怕猛虎，只怕人心不一、口是心非。", example: "合作最怕背叛，毋驚虎生三個喙，只驚人懷雙樣心。" },
  // 歇後語(25)
  { id: "s296", grade: 2, term: "螞蟻搬泰山──下定決心", kind: "歇後語", meaning: "決心極大，不畏艱難。", example: "他要自學考上第一志願，螞蟻搬泰山──下定決心。" },
  { id: "s297", grade: 2, term: "石沉大海──沒消息", kind: "歇後語", meaning: "毫無回音。", example: "投了十封履歷石沉大海──沒消息。" },
  { id: "s298", grade: 3, term: "貓抓玻璃──白費工", kind: "歇後語", meaning: "徒勞無功。", example: "勸不聽的人，說再多貓抓玻璃──白費工。" },
  { id: "s299", grade: 3, term: "洩了氣的皮球──軟了", kind: "歇後語", meaning: "失去信心鬥志。", example: "被拒絕兩次他就洩了氣的皮球──軟了。" },
  { id: "s300", grade: 3, term: "雨後春筍──一個勁往上冒", kind: "歇後語", meaning: "新事物大量湧現。", example: "手搖店雨後春筍──一個勁往上冒。" },
  { id: "s301", grade: 4, term: "芝麻掉進針眼裡──巧極了", kind: "歇後語", meaning: "非常湊巧。", example: "在京都遇到鄰居，芝麻掉進針眼裡──巧極了。" },
  { id: "s302", grade: 4, term: "冬天的甘蔗──甜到心裡", kind: "歇後語", meaning: "非常甜蜜開心。", example: "收到錄取通知，冬天的甘蔗──甜到心裡。" },
  { id: "s303", grade: 4, term: "山中無老虎──猴子稱大王", kind: "歇後語", meaning: "強者不在，次等的人便逞威風。", example: "隊長受傷缺陣，山中無老虎──猴子稱大王。" },
  { id: "s304", grade: 4, term: "隔岸觀火──袖手旁觀", kind: "歇後語", meaning: "見人危難而不救助。", example: "同學被欺負別隔岸觀火──袖手旁觀。" },
  { id: "s305", grade: 5, term: "獨眼龍看書──一目了然", kind: "歇後語", meaning: "諧音雙關:一看就明白。", example: "這張圖表獨眼龍看書──一目了然。" },
  { id: "s306", grade: 5, term: "騎驢看唱本──走著瞧", kind: "歇後語", meaning: "且看事情如何發展（帶較勁意味）。", example: "比賽還沒完，騎驢看唱本──走著瞧。" },
  { id: "s307", grade: 5, term: "打開天窗──說亮話", kind: "歇後語", meaning: "坦率直說，不遮掩。", example: "咱們打開天窗──說亮話，這案子問題在預算。" },
  { id: "s308", grade: 5, term: "快刀斬亂麻──乾脆俐落", kind: "歇後語", meaning: "果斷處理複雜問題。", example: "新主管快刀斬亂麻──乾脆俐落，砍掉冗餘流程。" },
  { id: "s309", grade: 6, term: "程咬金的斧頭──就這三下子", kind: "歇後語", meaning: "本領有限，招數不多。", example: "他的招式程咬金的斧頭──就這三下子。" },
  { id: "s310", grade: 6, term: "梁山泊的軍師──無(吳)用", kind: "歇後語", meaning: "諧音雙關:沒有用處。", example: "光出主意不動手，梁山泊的軍師──無用。" },
  { id: "s311", grade: 6, term: "潑出去的水──收不回", kind: "歇後語", meaning: "已成事實，無法挽回。", example: "話說出口就是潑出去的水──收不回。" },
  { id: "s312", grade: 6, term: "趕鴨子上架──強人所難", kind: "歇後語", meaning: "勉強別人做辦不到的事。", example: "叫我即興唱歌是趕鴨子上架──強人所難。" },
  { id: "s313", grade: 7, term: "楚河漢界──一清二楚", kind: "歇後語", meaning: "界線分明。", example: "帳目分開記，楚河漢界──一清二楚。" },
  { id: "s314", grade: 7, term: "黃牛過河──各顧各", kind: "歇後語", meaning: "只顧自己，互不相助。", example: "小組作業大家黃牛過河──各顧各，慘不忍睹。" },
  { id: "s315", grade: 7, term: "啞巴打官司──有理說不出", kind: "歇後語", meaning: "有道理卻無法申辯。", example: "沒留存證據，啞巴打官司──有理說不出。" },
  { id: "s316", grade: 8, term: "鐵公雞──一毛不拔", kind: "歇後語", meaning: "極度吝嗇。", example: "找他募款？鐵公雞──一毛不拔。" },
  { id: "s317", grade: 8, term: "屬算盤的──撥一撥動一動", kind: "歇後語", meaning: "被動，不推不動。", example: "他做事屬算盤的──撥一撥動一動。" },
  { id: "s318", grade: 8, term: "戲台底下掉眼淚──替古人擔憂", kind: "歇後語", meaning: "為不相干的事白操心。", example: "劇情是虛構的，別戲台底下掉眼淚──替古人擔憂。" },
  { id: "s319", grade: 9, term: "諸葛亮當軍師──名副其實", kind: "歇後語", meaning: "名聲與才能相符。", example: "請她當顧問是諸葛亮當軍師──名副其實。" },
  { id: "s320", grade: 9, term: "曹操吃雞肋──食之無味，棄之可惜", kind: "歇後語", meaning: "沒多大價值，丟掉又捨不得。", example: "這個舊專案曹操吃雞肋──食之無味，棄之可惜。" },,
  { id: "s321", grade: 1, term: "馬馬虎虎", kind: "俚語", meaning: "形容做事隨便、不認真仔細，也可指程度普通。", example: "寫功課不能馬馬虎虎，寫完要記得檢查一遍。" },
  { id: "s322", grade: 1, term: "人小志氣高", kind: "諺語", meaning: "年紀或個子雖小，志向卻很遠大，值得稱讚。", example: "他才小學一年級就立志當醫生，真是人小志氣高。" },
  { id: "s323", grade: 1, term: "十五的月亮——圓圓滿滿", kind: "歇後語", meaning: "農曆十五的月亮最圓，比喻事情圓滿、家人團圓。", example: "全家人聚在一起吃團圓飯，真像十五的月亮——圓圓滿滿。" },
  { id: "s324", grade: 1, term: "放鴿子", kind: "俚語", meaning: "比喻和人約好了卻故意不出現，讓對方白等。", example: "他昨天放我鴿子，害我在公園等了半個小時。" },
  { id: "s325", grade: 1, term: "助人為快樂之本", kind: "諺語", meaning: "幫助別人是快樂的根源，鼓勵人多行善事。", example: "老師常說助人為快樂之本，所以我很喜歡當小幫手。" },
  { id: "s326", grade: 2, term: "一勤天下無難事", kind: "諺語", meaning: "只要勤勞肯做，天下就沒有辦不成的事。", example: "爸爸靠著早起晚睡把小店做起來，真是一勤天下無難事。" },
  { id: "s327", grade: 2, term: "八月十五的月餅——人人有份", kind: "歇後語", meaning: "中秋節分月餅每個人都有，比喻好處大家共享，誰也不缺。", example: "班上得到的獎品，就像八月十五的月餅——人人有份。" },
  { id: "s328", grade: 2, term: "潑冷水", kind: "俚語", meaning: "比喻在別人興頭上說洩氣話，打擊對方的熱情。", example: "他才說要參加比賽，你就潑冷水，太不夠意思了。" },
  { id: "s329", grade: 3, term: "碰釘子", kind: "俚語", meaning: "比喻做事遭到拒絕或受到挫折。", example: "他去借球被拒絕，碰了個釘子，垂頭喪氣地回來。" },
  { id: "s330", grade: 3, term: "打鐵趁熱", kind: "諺語", meaning: "打鐵要趁鐵燒紅時，比喻做事要把握最好的時機，一鼓作氣。", example: "老師剛教完，我們打鐵趁熱馬上練習，印象最深刻。" },
  { id: "s331", grade: 4, term: "打破砂鍋——問到底", kind: "歇後語", meaning: "「璺」（裂紋）到底諧音「問到底」，形容追根究柢，非弄清楚不可。", example: "他對什麼都好奇，凡事像打破砂鍋——問到底。" },
  { id: "s332", grade: 4, term: "無風不起浪", kind: "諺語", meaning: "沒有風就不會起浪，比喻事情的發生總有原因，傳聞多半有來由。", example: "無風不起浪，這件事會傳開，恐怕不是完全沒根據。" },
  { id: "s333", grade: 5, term: "馬後炮", kind: "俚語", meaning: "象棋術語借來比喻事情過後才提意見或補救，已經無濟於事。", example: "比賽輸了你才說早知道要換人，這不是放馬後炮嗎？" },
  { id: "s334", grade: 5, term: "三天打魚，兩天曬網", kind: "諺語", meaning: "比喻做事沒有恆心，時常中斷，斷斷續續難有成果。", example: "學琴要每天練，三天打魚，兩天曬網是學不好的。" },
  { id: "s335", grade: 6, term: "半路出家", kind: "俚語", meaning: "原指成年後才出家，比喻中途改行，不是本行出身。", example: "他本來是廚師，半路出家學攝影，卻拍出了名氣。" },
  { id: "s336", grade: 6, term: "留一手", kind: "俚語", meaning: "比喻不把本領全部拿出來或教給別人，保留一部分。", example: "師傅教徒弟總愛留一手，關鍵的火候只有他自己知道。" },
  { id: "s337", grade: 6, term: "解鈴還須繫鈴人", kind: "諺語", meaning: "鈴是誰繫上的就該由誰解下，比喻問題該由造成的人去解決。", example: "他們兩人的誤會，解鈴還須繫鈴人，還是得阿明自己去道歉。" },
  { id: "s338", grade: 6, term: "孫猴子的臉——說變就變", kind: "歇後語", meaning: "孫悟空會七十二變，比喻人的臉色、態度或事情變化非常快。", example: "山上的天氣像孫猴子的臉——說變就變，記得帶雨衣。" },
  { id: "s339", grade: 7, term: "磨刀不誤砍柴工", kind: "諺語", meaning: "先把刀磨利，砍柴反而更快，比喻事前準備充分，能提高效率不算耽誤。", example: "先把讀書計畫排好再開始，磨刀不誤砍柴工。" },
  { id: "s340", grade: 7, term: "換湯不換藥", kind: "俚語", meaning: "湯換了藥沒換，比喻只改變形式，內容和本質依舊。", example: "新規定只是把名稱改了，內容換湯不換藥。" },
  { id: "s341", grade: 7, term: "水仙不開花——裝蒜", kind: "歇後語", meaning: "水仙不開花時樣子像蒜，比喻明明知道卻假裝不知道、裝糊塗。", example: "明明是你拿走的，還在那裡水仙不開花——裝蒜。" },
  { id: "s342", grade: 8, term: "路遙知馬力，日久見人心", kind: "諺語", meaning: "路途遠才知道馬的耐力，相處久才看得出人心的真假。", example: "他默默幫了我們這麼多年，路遙知馬力，日久見人心。" },
  { id: "s343", grade: 8, term: "世上無難事，只怕有心人", kind: "諺語", meaning: "只要有決心、肯下功夫，再難的事也能辦成。", example: "世上無難事，只怕有心人，他自學三年終於考上了。" },
  { id: "s344", grade: 8, term: "打腫臉充胖子", kind: "俚語", meaning: "比喻明明沒有實力，硬撐場面裝作了不起。", example: "收入不多卻硬要買名牌，何必打腫臉充胖子？" },
  { id: "s345", grade: 8, term: "掛羊頭賣狗肉", kind: "俚語", meaning: "招牌上掛羊頭，實際賣狗肉，比喻表裡不一，用好名目做欺騙的事。", example: "號稱有機蔬菜卻來路不明，根本是掛羊頭賣狗肉。" },
  { id: "s346", grade: 8, term: "秋後的螞蚱——蹦躂不了幾天", kind: "歇後語", meaning: "入秋天冷螞蚱將死，比喻壞人或敗勢已定的事撐不了多久。", example: "詐騙集團再囂張，也是秋後的螞蚱——蹦躂不了幾天。" },
  { id: "s347", grade: 9, term: "十年樹木，百年樹人", kind: "諺語", meaning: "培植樹木要十年，培育人才要百年，比喻教育是長遠大計。", example: "十年樹木，百年樹人，辦教育急不得。" },
  { id: "s348", grade: 9, term: "學如逆水行舟，不進則退", kind: "諺語", meaning: "學習像逆著水流行船，不努力前進就會後退。", example: "放假也要溫習，學如逆水行舟，不進則退。" },
  { id: "s349", grade: 9, term: "真金不怕火煉", kind: "諺語", meaning: "真正的黃金不怕烈火鍛煉，比喻真才實學或清白經得起考驗。", example: "儘管流言四起，他仍坦然面對，真金不怕火煉。" },
  { id: "s350", grade: 9, term: "紙包不住火", kind: "諺語", meaning: "紙終究包不住火，比喻真相或壞事隱瞞不了，遲早會暴露。", example: "犯了錯就趕快承認，紙包不住火，拖越久越糟。" },
  { id: "s351", grade: 9, term: "上樑不正下樑歪", kind: "諺語", meaning: "上面的樑歪了，下面的樑也會跟著歪，比喻在上位者行為不正，下面的人就會跟著學壞。", example: "主管帶頭虛報帳目，上樑不正下樑歪，部門風氣才會敗壞。" },
  { id: "s352", grade: 9, term: "穿小鞋", kind: "俚語", meaning: "比喻暗中刁難、報復別人，給人吃暗虧。", example: "他因為說了實話，就被主管穿小鞋，處處刁難。" },
  { id: "s353", grade: 9, term: "敲竹槓", kind: "俚語", meaning: "比喻利用別人的弱點或藉機抬高價錢，索取財物。", example: "觀光區有些店家專敲遊客竹槓，一瓶水賣三倍價。" },
  { id: "s354", grade: 9, term: "下馬威", kind: "俚語", meaning: "原指官員上任時先顯威風，比喻一開始就給人厲害的顏色看。", example: "新教練第一天就加練體能，給大家來了個下馬威。" },
  { id: "s355", grade: 9, term: "黃連樹下彈琴——苦中作樂", kind: "歇後語", meaning: "黃連極苦，在黃連樹下彈琴，比喻在困苦的處境中自尋樂趣。", example: "工地生活辛苦，他們晚上圍著唱歌，黃連樹下彈琴——苦中作樂。" },
  { id: "s356", grade: 9, term: "老鼠鑽風箱——兩頭受氣", kind: "歇後語", meaning: "風箱兩頭進出風，老鼠鑽進去兩邊都挨吹，比喻夾在中間兩面不討好。", example: "他夾在婆媳之間，老鼠鑽風箱——兩頭受氣。" },
  { id: "s357", grade: 10, term: "疾風知勁草", kind: "諺語", meaning: "狂風中才看得出哪株草堅韌不倒，比喻危難時刻才能考驗出人的堅強品格。", example: "公司最困難時他不離不棄，疾風知勁草，患難見真情。" },
  { id: "s358", grade: 10, term: "山雨欲來風滿樓", kind: "諺語", meaning: "大雨來臨前滿樓狂風，比喻重大事件爆發前，已有緊張的徵兆和氣氛。", example: "兩家公司高層頻頻放話，山雨欲來風滿樓，購併戰恐怕一觸即發。" },
  { id: "s359", grade: 10, term: "塞翁失馬，焉知非福", kind: "諺語", meaning: "邊塞老翁丟了馬反而因禍得福，比喻一時的損失未必是壞事，禍福常會互相轉化。", example: "沒考上第一志願反而遇到好老師，塞翁失馬，焉知非福。" },
  { id: "s360", grade: 10, term: "巧婦難為無米之炊", kind: "諺語", meaning: "再能幹的主婦沒有米也煮不出飯，比喻缺乏必要條件，再有本事也難成事。", example: "沒有預算什麼活動都辦不成，巧婦難為無米之炊。" },
  { id: "s361", grade: 10, term: "良禽擇木而棲", kind: "諺語", meaning: "好鳥會選擇良木築巢，比喻賢者會選擇值得效力的對象或環境。", example: "良禽擇木而棲，人才自然流向重視他們的公司。" },
  { id: "s362", grade: 10, term: "人往高處走，水往低處流", kind: "諺語", meaning: "人應該力求上進，就像水自然往低處流一樣是常理。", example: "他決定出國進修，人往高處走，大家都祝福他。" },
  { id: "s363", grade: 10, term: "兵來將擋，水來土掩", kind: "諺語", meaning: "敵兵來了派將抵擋，大水來了用土掩蓋，比喻不管遇到什麼情況，都有相應的辦法對付。", example: "對手出什麼招都別慌，兵來將擋，水來土掩。" },
  { id: "s364", grade: 10, term: "車到山前必有路", kind: "諺語", meaning: "車行到山前自然會出現道路，比喻事到臨頭總會有解決的辦法，不必過分憂慮。", example: "先別擔心經費，車到山前必有路，一步一步來。" },
  { id: "s365", grade: 10, term: "樹倒猢猻散", kind: "諺語", meaning: "大樹倒了，樹上的猴子一哄而散，比喻有權勢的人一垮台，依附的人便紛紛離去。", example: "董事長一被收押，昔日圍著他的人全不見了，正是樹倒猢猻散。" },
  { id: "s366", grade: 10, term: "有燒香有保庇", kind: "俚語", meaning: "（台語）有燒香就有神明保佑，比喻有付出、有準備，總會有相應的回報。", example: "平時有練習有實力，有燒香有保庇，上場就不怕。" },
  { id: "s367", grade: 10, term: "牛牽到北京嘛是牛", kind: "俚語", meaning: "（台語）牛就算牽到北京還是牛，比喻本性難改，換了環境依然故我。", example: "他到新公司還是遲到，唉，牛牽到北京嘛是牛。" },
  { id: "s368", grade: 10, term: "破天荒", kind: "俚語", meaning: "唐代荊州多年無人考中進士，稱「天荒」，後有人考中打破紀錄，比喻從未有過、頭一次發生的事。", example: "他破天荒主動留下來打掃，大家都嚇了一跳。" },
  { id: "s369", grade: 10, term: "打圓場", kind: "俚語", meaning: "比喻出面調解尷尬或僵持的場面，讓雙方都有台階下。", example: "兩人吵得下不了台，還好班長出來打圓場。" },
  { id: "s370", grade: 10, term: "張飛繡花——粗中有細", kind: "歇後語", meaning: "猛將張飛做細活，比喻外表粗獷的人做事也有細心的一面。", example: "別看他大剌剌的，帳目記得一清二楚，張飛繡花——粗中有細。" },
  { id: "s371", grade: 11, term: "由儉入奢易，由奢入儉難", kind: "諺語", meaning: "從節儉變奢侈很容易，從奢侈回到節儉卻很難，勸人守住儉樸的生活習慣。", example: "富起來也別亂花，由儉入奢易，由奢入儉難。" },
  { id: "s372", grade: 11, term: "良言一句三冬暖，惡語傷人六月寒", kind: "諺語", meaning: "一句善意的話讓人在寒冬也覺得溫暖，一句惡毒的話讓人在盛夏也感到心寒，勸人謹慎言語。", example: "說話前多想想，良言一句三冬暖，惡語傷人六月寒。" },
  { id: "s373", grade: 11, term: "靜坐常思己過，閒談莫論人非", kind: "諺語", meaning: "獨處時常反省自己的過錯，閒聊時不要議論別人的是非，是修身處世的格言。", example: "把「靜坐常思己過，閒談莫論人非」貼在書桌前提醒自己。" },
  { id: "s374", grade: 11, term: "來說是非者，便是是非人", kind: "諺語", meaning: "主動來搬弄是非的人，本身往往就是製造是非的人，提醒人提防搬弄口舌者。", example: "他一來就數落同事不是，來說是非者，便是是非人，聽聽就好。" },
  { id: "s375", grade: 11, term: "有理走遍天下，無理寸步難行", kind: "諺語", meaning: "有道理到哪裡都行得通，沒道理則處處受阻，強調做事要站得住理。", example: "不用怕對方聲音大，有理走遍天下，無理寸步難行。" },
  { id: "s376", grade: 11, term: "只許州官放火，不許百姓點燈", kind: "諺語", meaning: "官員自己放火卻不准百姓點燈，比喻在上位者自己胡作非為，卻嚴禁他人正當行為的雙重標準。", example: "主管自己天天遲到卻嚴懲部屬，真是只許州官放火，不許百姓點燈。" },
  { id: "s377", grade: 11, term: "聽君一席話，勝讀十年書", kind: "諺語", meaning: "聽對方一番話，勝過苦讀十年書，形容別人的見解使自己受益極大。", example: "前輩把行業門道一一點破，聽君一席話，勝讀十年書。" },
  { id: "s378", grade: 11, term: "行百里者半九十", kind: "諺語", meaning: "走一百里路，走了九十里只能算走一半，比喻越接近成功越艱難，越要堅持到底。", example: "論文只剩最後一章更要穩住，行百里者半九十。" },
  { id: "s379", grade: 11, term: "食米毋知米價", kind: "俚語", meaning: "（台語）吃米卻不知道米的價錢，比喻不知人間疾苦、不懂生活現實。", example: "伸手要錢卻嫌爸媽小氣，真是食米毋知米價。" },
  { id: "s380", grade: 11, term: "近山剉無柴，近溪擔無水", kind: "俚語", meaning: "（台語）住在山邊反而沒柴燒，住在溪邊反而沒水挑，比喻擁有便利條件反而不知珍惜利用。", example: "住在圖書館對面卻從不進去，近山剉無柴，近溪擔無水。" },
  { id: "s381", grade: 11, term: "未曾學行先學飛", kind: "俚語", meaning: "（台語）還沒學會走路就想學飛，比喻不按部就班，好高騖遠。", example: "基本功都沒練就想挑戰高難度，未曾學行先學飛。" },
  { id: "s382", grade: 11, term: "有量才有福", kind: "俚語", meaning: "（台語）有度量的人才有福氣，勸人心胸寬大、不斤斤計較。", example: "跟人計較這些小事做什麼？有量才有福啦。" },
  { id: "s383", grade: 11, term: "灶王爺上天——有一說一", kind: "歇後語", meaning: "傳說灶神年終上天稟報人間事，比喻據實直說，不誇大也不隱瞞。", example: "問他什麼都直說，灶王爺上天——有一說一。" },
  { id: "s384", grade: 11, term: "唐僧念經——一本正經", kind: "歇後語", meaning: "唐僧念經自然正經專注，形容態度莊重認真，有時也帶點嘲諷過於古板。", example: "他連玩桌遊都唐僧念經——一本正經地宣讀規則。" },
  { id: "s385", grade: 11, term: "木匠戴枷——自作自受", kind: "歇後語", meaning: "枷是木匠做的，木匠自己戴上，比喻自己做的錯事，由自己承擔惡果。", example: "熬夜打電動隔天考試睡著，木匠戴枷——自作自受。" },
  { id: "s386", grade: 12, term: "天下興亡，匹夫有責", kind: "諺語", meaning: "國家民族的興盛衰亡，每一個平民都有責任。", example: "他投身公共事務，抱的是天下興亡，匹夫有責的信念。" },
  { id: "s387", grade: 12, term: "疑人不用，用人不疑", kind: "諺語", meaning: "懷疑的人就不要任用，既然任用就要充分信任，是用人的基本原則。", example: "老闆敢放手讓年輕人做決定，疑人不用，用人不疑。" },
  { id: "s388", grade: 12, term: "千軍易得，一將難求", kind: "諺語", meaning: "招募千軍容易，尋得一位良將困難，比喻傑出的領導人才極為難得。", example: "公司不怕缺人手，怕的是千軍易得，一將難求。" },
  { id: "s389", grade: 12, term: "擒賊先擒王", kind: "諺語", meaning: "捉賊要先捉首領，比喻解決問題要先抓住關鍵或核心。", example: "要整頓交通亂象，先從違規大戶開罰，擒賊先擒王。" },
  { id: "s390", grade: 12, term: "木秀於林，風必摧之", kind: "諺語", meaning: "樹木高出樹林，風必先吹折它，比喻人才出眾或鋒芒太露，容易招致嫉妒與打擊。", example: "他年紀輕輕升上高位便流言纏身，正是木秀於林，風必摧之。" },
  { id: "s391", grade: 12, term: "智者千慮，必有一失", kind: "諺語", meaning: "再聰明的人考慮再周密，也難免有疏漏，提醒人不可自恃聰明。", example: "計畫再完備也要留備案，智者千慮，必有一失。" },
  { id: "s392", grade: 12, term: "不怕慢，只怕站", kind: "諺語", meaning: "進步慢不要緊，最怕停下來不動，勉勵人持續前進。", example: "每天背十個單字就好，不怕慢，只怕站。" },
  { id: "s393", grade: 12, term: "強龍不壓地頭蛇", kind: "諺語", meaning: "再強的外來勢力，也難壓制盤據當地的勢力，比喻外來者須尊重在地實力。", example: "國際大廠來台展店也得入境隨俗，強龍不壓地頭蛇。" },
  { id: "s394", grade: 12, term: "贏贏筊，跋甲輸輸去", kind: "俚語", meaning: "（台語）本來穩贏的賭局，卻打到輸光，比喻大好局面因輕忽或貪心而斷送。", example: "領先二十分還輸球，真是贏贏筊，跋甲輸輸去。" },
  { id: "s395", grade: 12, term: "在生一粒豆，較贏死了拜豬頭", kind: "俚語", meaning: "（台語）父母在世時奉養一粒豆子，勝過死後用豬頭祭拜，勸人及時行孝。", example: "有空多回家陪爸媽，在生一粒豆，較贏死了拜豬頭。" },
  { id: "s396", grade: 12, term: "好田地，不如好子弟", kind: "俚語", meaning: "（台語）留給子孫良田，不如把子孫教育好，強調教養重於財產。", example: "阿公不留房產卻堅持栽培孫子讀書，他說好田地，不如好子弟。" },
  { id: "s397", grade: 12, term: "歹瓜厚籽，歹人厚言語", kind: "俚語", meaning: "（台語）不好的瓜籽特別多，品行差的人藉口和閒話特別多，諷刺多辯多話之人。", example: "他犯了錯理由一大堆，正是歹瓜厚籽，歹人厚言語。" },
  { id: "s398", grade: 12, term: "白骨精遇上孫悟空——原形畢露", kind: "歇後語", meaning: "白骨精再會變化也逃不過孫悟空的火眼金睛，比喻偽裝在行家面前徹底暴露。", example: "假幣一放進驗鈔機，白骨精遇上孫悟空——原形畢露。" },
  { id: "s399", grade: 12, term: "擺渡不成翻了船——弄巧成拙", kind: "歇後語", meaning: "想幫人渡河卻把船弄翻，比喻本想取巧做好事，反而把事情搞砸。", example: "他想幫同學圓謊結果越描越黑，擺渡不成翻了船——弄巧成拙。" },
  { id: "s400", grade: 12, term: "愚公的居處——開門見山", kind: "歇後語", meaning: "傳說愚公家門正對太行、王屋二山，比喻說話或寫文章直截了當，一開頭就進入正題。", example: "他報告一開場就先講結論，愚公的居處——開門見山。" },
  // 2026-08-07 擴充批次一（s401-s420）
  { id: "s401", grade: 2, term: "一分耕耘，一分收穫", kind: "諺語", meaning: "付出多少努力，就得到多少成果；成果與努力成正比。", example: "他每天苦練投籃終於入選校隊，真是一分耕耘，一分收穫。" },
  { id: "s402", grade: 2, term: "玉不琢，不成器", kind: "諺語", meaning: "玉石不經雕琢就不能成為器物，比喻人不學習磨練就難以成材。", example: "教練嚴格要求大家：玉不琢，不成器，吃苦是為你們好。" },
  { id: "s403", grade: 3, term: "人外有人，天外有天", kind: "諺語", meaning: "強中更有強中手，提醒人不可自滿。", example: "他拿了縣賽冠軍就自誇第一，到了全國賽才知道人外有人，天外有天。" },
  { id: "s404", grade: 3, term: "不經一事，不長一智", kind: "諺語", meaning: "不親身經歷一件事，就不會增長處理那件事的智慧；經驗使人成長。", example: "第一次露營手忙腳亂，不經一事，不長一智，下次就熟練了。" },
  { id: "s405", grade: 4, term: "人心齊，泰山移", kind: "諺語", meaning: "大家同心協力，連泰山都能搬動，比喻團結就能發揮巨大的力量。", example: "全班分工合作布置會場，人心齊，泰山移，一個下午就完成了。" },
  { id: "s406", grade: 4, term: "入境隨俗", kind: "諺語", meaning: "到一個地方，就順從當地的風俗習慣。", example: "到日本泡溫泉要先沖洗身體，入境隨俗，別失了禮數。" },
  { id: "s407", grade: 5, term: "啞子吃湯圓——心裡有數", kind: "歇後語", meaning: "啞巴吃了幾顆湯圓說不出來，但自己清楚，比喻心中明白，只是不說。", example: "這次考得如何他嘴上不講，啞子吃湯圓——心裡有數。" },
  { id: "s408", grade: 5, term: "近朱者赤，近墨者黑", kind: "諺語", meaning: "接近硃砂會變紅，接近墨會變黑，比喻環境與朋友對人的影響很大。", example: "近朱者赤，近墨者黑，跟自律的同學同組，你也會跟著認真。" },
  { id: "s409", grade: 6, term: "三個臭皮匠，勝過一個諸葛亮", kind: "諺語", meaning: "幾個平凡人集思廣益，勝過一個聰明人單打獨鬥；比喻眾人智慧可貴。", example: "大家一起想辦法吧，三個臭皮匠，勝過一個諸葛亮。" },
  { id: "s410", grade: 6, term: "隔行如隔山", kind: "諺語", meaning: "不同行業之間差異極大，外行人難以了解另一行的門道。", example: "別看修錶好像簡單，隔行如隔山，沒學過根本無從下手。" },
  { id: "s411", grade: 7, term: "好漢不吃眼前虧", kind: "俚語", meaning: "聰明人懂得避開眼前明顯不利的處境，先保全自己再作打算。", example: "對方人多勢眾，好漢不吃眼前虧，我們先離開再報警處理。" },
  { id: "s412", grade: 7, term: "熟讀唐詩三百首，不會作詩也會吟", kind: "諺語", meaning: "反覆熟讀名作，即使不會創作也能吟誦模仿；強調熟讀與累積的功效。", example: "多背範文吧，熟讀唐詩三百首，不會作詩也會吟，作文自然進步。" },
  { id: "s413", grade: 8, term: "心急吃不了熱豆腐", kind: "俚語", meaning: "豆腐太燙急著吃會燙嘴，比喻做事急躁反而辦不成，要有耐心。", example: "申請流程要一關一關來，心急吃不了熱豆腐。" },
  { id: "s414", grade: 8, term: "江山易改，本性難移", kind: "諺語", meaning: "山河面貌都比人的本性容易改變，形容人的性格習氣極難改變。", example: "他戒了又犯、犯了又戒，唉，江山易改，本性難移。" },
  { id: "s415", grade: 9, term: "騎驢找馬", kind: "俚語", meaning: "先將就目前的位置，同時另尋更好的機會，多指一邊工作一邊找新職。", example: "這份工作先做著，騎驢找馬，有更好的缺再跳槽。" },
  { id: "s416", grade: 9, term: "放長線，釣大魚", kind: "俚語", meaning: "把釣線放長才能釣到大魚，比喻從長計議、先投入耐心以獲取更大的成果。", example: "警方沒有立刻收網，而是放長線，釣大魚，要一舉逮捕幕後主嫌。" },
  { id: "s417", grade: 10, term: "貪小便宜吃大虧", kind: "俚語", meaning: "為了貪圖眼前的小利益，結果蒙受更大的損失。", example: "路邊來歷不明的廉價手機別買，小心貪小便宜吃大虧。" },
  { id: "s418", grade: 10, term: "人怕出名豬怕肥", kind: "俚語", meaning: "豬養肥了就會被宰，人出了名便容易招來麻煩與是非。", example: "他中樂透後親戚紛紛上門借錢，真是人怕出名豬怕肥。" },
  { id: "s419", grade: 11, term: "吃虧就是占便宜", kind: "俚語", meaning: "表面上吃了虧，實際上可能累積信用、人緣或經驗，反而獲益。", example: "多做一點不會少塊肉，吃虧就是占便宜，主管都看在眼裡。" },
  { id: "s420", grade: 12, term: "船過水無痕", kind: "諺語", meaning: "船駛過水面不留痕跡，比喻事情過後不留影響，或譏人事過即忘、不念舊情。", example: "當年大家幫他度過難關，如今他船過水無痕，一句感謝也沒有。" },
  { id: "s421", grade: 5, term: "頭過身就過", kind: "俚語", meaning: "台語俗諺：頭鑽得過去，身體就跟著過得去，比喻最難的第一關通過了，後面就順利了。", example: "第一次上台最緊張，頭過身就過，之後你就敢講了。" },
  { id: "s422", grade: 6, term: "曲不離口，拳不離手", kind: "諺語", meaning: "唱曲要常開口練，打拳要常動手練，比喻技藝必須天天練習才不會生疏。", example: "老師勉勵我們曲不離口，拳不離手，樂器一天不碰就會退步。" },
  { id: "s423", grade: 6, term: "甘蔗無雙頭甜", kind: "諺語", meaning: "台語俗諺：甘蔗不會兩頭都甜，比喻凡事難以十全十美，有所得必有所失。", example: "想住市中心又要房租便宜？甘蔗無雙頭甜，總得取捨。" },
  { id: "s424", grade: 7, term: "目睭花花，匏仔看做菜瓜", kind: "俚語", meaning: "台語俗諺：眼睛昏花，把匏瓜看成絲瓜，笑人看走了眼、認錯對象或東西。", example: "那不是你同學啦，你目睭花花，匏仔看做菜瓜。" },
  { id: "s425", grade: 8, term: "生食都無夠，哪有通曝乾", kind: "諺語", meaning: "台語俗諺：生吃都不夠了，哪還有多餘的拿去曬成乾？比喻收入僅夠餬口，毫無剩餘可儲存。", example: "薪水繳完房租就見底，生食都無夠，哪有通曝乾，怎麼存錢？" },
  { id: "s426", grade: 8, term: "嘴上無毛，辦事不牢", kind: "俚語", meaning: "譏笑人年輕、閱歷淺，做事不夠穩當可靠。", example: "老師傅起初嫌他嘴上無毛，辦事不牢，後來卻對他的細心刮目相看。" },
  { id: "s427", grade: 9, term: "三年一閏，好歹照輪", kind: "諺語", meaning: "台語俗諺：曆法三年一閏、循環有序，比喻運勢好壞輪流轉，不會永遠是同一人得意或失意。", example: "別得意得太早，三年一閏，好歹照輪，風水輪流轉。" },
  { id: "s428", grade: 10, term: "別人的囝死袂了", kind: "諺語", meaning: "台語俗諺：反正死的是別人的孩子，死不完也不心疼，譏諷人自私冷血，慷他人之慨、不顧他人死活。", example: "把危險的工作全推給新人，真是別人的囝死袂了。" }
];
